UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/cq8k-electric-children-bed-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cama pediátrica eléctrica hospitalaria Saikang CQ8k concentra cinco funciones clínicas en un equipo pensado para unidades pediátricas en Colombia: dos motores lineales mueven altura (480–770 mm), respaldo (0–75°), piernas (0–35°) y Trendelenburg e inverso (0–12°), de modo que el equipo de enfermería puede reposicionar al paciente sin esfuerzo manual excesivo.

Su plataforma de PP lavable con retenedor de colchón integrado, rieles de aleación de aluminio con protección adicional y cabecera/piecero de PP con bloqueo seguro facilitan la higiene y la contención. El acero Baosteel con soldadura robótica Panasonic y el plástico esterilizable a 100 °C respaldan la durabilidad hospitalaria que exigen los compradores institucionales.

Con carga máxima de 200 kg, ruedas dobles de 5" con bloqueo central, soporte de suero y ganchos de drenaje de serie —y opcionales como barra con triángulo de Balkan o ruedas direccionales— la CQ8k ofrece movilidad y accesorios listos para la rutina de pediatría.$d$,
  descripcion_larga_en = $d$The Saikang CQ8k electric paediatric bed brings five clinical functions into a unit suited to paediatric wards in Colombia: two linear motors drive height (480–770 mm), backrest (0–75°), legs (0–35°) and Trendelenburg and reverse (0–12°), so nursing teams can reposition the patient without heavy manual effort.

Its washable PP platform with integrated mattress retainer, aluminium-alloy side rails with extra protection and PP head/foot boards with secure locking support hygiene and containment. Baosteel steel with Panasonic robotic welding and plastic sterilizable at 100 °C back the hospital-grade durability institutional buyers expect.

With a 200 kg maximum load, dual 5" casters with central lock, IV pole and drainage hooks as standard —plus options such as a Balkan frame or directional casters— the CQ8k delivers mobility and accessories ready for paediatric routines.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"CQ8k"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones de la cama","grupo":"Dimensiones","valor":"1975 x 880 x 480-770 mm"},{"clave":"Plataforma","grupo":"Dimensiones","valor":"1730 x 780 mm"},{"clave":"Carga máxima","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"0-75° / 0-35°"},{"clave":"Trendelenburg / inverso","grupo":"Ajustes","valor":"0-12° / 0-12°"},{"clave":"Motores","grupo":"Configuración","valor":"2 lineales"},{"clave":"Ruedas","grupo":"Configuración","valor":"4 de 5\" con bloqueo central"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plataforma PP lavable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño sin gérmenes"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Opcional: trapecio, ruedas direccionales"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Hospitalización pediátrica","Unidades de cuidado infantil","Reposición y Trendelenburg en cama","Movilización intradepartamental con ruedas bloqueables"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Paediatric inpatient care","Children's care units","In-bed repositioning and Trendelenburg","Intradepartmental transfer with lockable casters"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cinco funciones con dos motores lineales: altura 480–770 mm, respaldo 0–75°, piernas 0–35° y Trendelenburg/inverso 0–12°.","Plataforma de PP lavable con retenedor de colchón y rieles de aluminio con protección adicional para higiene y seguridad.","Acero Baosteel con soldadura robótica y plástico esterilizable a 100 °C para un mobiliario médico de larga vida útil.","Ruedas dobles de 5\" con bloqueo central, soporte de suero y ganchos de drenaje; opcionales Balkan y ruedas direccionales."],"beneficios_en":["Five functions with two linear motors: height 480–770 mm, backrest 0–75°, legs 0–35° and Trendelenburg/reverse 0–12°.","Washable PP platform with mattress retainer and aluminium rails with extra protection for hygiene and safety.","Baosteel steel with robotic welding and plastic sterilizable at 100 °C for long-life medical furniture.","Dual 5\" casters with central lock, IV pole and drainage hooks; Balkan frame and directional casters optional."],"valor_es":"Una cama pediátrica eléctrica de 200 kg con plataforma lavable, rieles protegidos y Trendelenburg, documentada en la ficha oficial Saikang.","valor_en":"A 200 kg electric paediatric bed with washable platform, protected rails and Trendelenburg, documented in the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga máxima admite la CQ8k?","a":"La carga máxima admisible es de 200 kg, según la ficha técnica Saikang."},{"q":"¿Qué ángulos de ajuste ofrece?","a":"Respaldo 0–75°, piernas 0–35°, Trendelenburg 0–12° e inverso 0–12°, además de altura de 480 a 770 mm."},{"q":"¿Qué accesorios opcionales tiene?","a":"Barra con triángulo de Balkan y ruedas direccionales, además del soporte de suero y ganchos de drenaje de serie."},{"q":"¿Dónde descargo la ficha técnica de Cama de Atención Pediátrica CQ8k?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What maximum load does the CQ8k support?","a":"The maximum allowable load is 200 kg, per the Saikang datasheet."},{"q":"What adjustment angles does it offer?","a":"Backrest 0–75°, legs 0–35°, Trendelenburg 0–12° and reverse 0–12°, plus height from 480 to 770 mm."},{"q":"What optional accessories are available?","a":"Balkan frame and directional casters, in addition to the standard IV pole and drainage hooks."},{"q":"Where can I download the Pediatric Care Bed CQ8k datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cama pediátrica eléctrica hospitalaria","cama pediátrica CQ8k Saikang","cama eléctrica infantil Colombia","cama pediátrica Trendelenburg","mobiliario pediátrico hospitalario","cama 5 funciones pediatría","ficha técnica CQ8k Saikang"],"seo_keywords_en":["electric paediatric hospital bed","CQ8k Saikang paediatric bed","electric children bed Colombia","paediatric Trendelenburg bed","paediatric hospital furniture","5-function paediatric bed","CQ8k Saikang datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/CQ8k_Electric-Children-Bed_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'cama-de-atencion-pediatrica-ref-cq8k-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/x01-baby-crib-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cuna neonatal hospitalaria Saikang X01 es una cuna de bebé compacta (810 × 490 × 960 mm) pensada para maternidad y neonatología en Colombia. Su lavabo transparente de acrílico no tóxico, esterilizable a más de 100 °C, permite observar al recién nacido con claridad mientras el marco de acero inoxidable Baosteel aporta la rigidez que espera el comprador institucional.

Incluye porta suero de acero inoxidable (hasta 15 kg), cuatro ruedas de 5" (dos con freno) y elementos a prueba de polvo. El colchón personalizado, suave y de fácil limpieza, completa un conjunto listo para la rutina de puerperio y observación neonatal.

El Trendelenburg controlado por estructura mecánica facilita inclinaciones convenientes para el cuidado, sin añadir complejidad eléctrica al equipo.$d$,
  descripcion_larga_en = $d$The Saikang X01 neonatal crib is a compact hospital baby crib (810 × 490 × 960 mm) designed for maternity and neonatology in Colombia. Its clear non-toxic acrylic bassinet, sterilizable above 100 °C, keeps the newborn visible while the Baosteel stainless-steel frame delivers the rigidity institutional buyers expect.

It includes a stainless-steel IV pole (up to 15 kg), four 5" casters (two with brakes) and dust-proof elements. A custom soft, easy-to-clean mattress completes a set ready for postpartum and neonatal observation routines.

Mechanically controlled Trendelenburg supports convenient tilt for care without adding electrical complexity to the unit.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"X01"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas (L x A x H)","grupo":"Dimensiones","valor":"810 x 490 x 960 mm"},{"clave":"Marco","grupo":"Material","valor":"Acero inoxidable"},{"clave":"Lavabo","grupo":"Material","valor":"Acrílico transparente no tóxico, esterilizable > 100 °C"},{"clave":"Porta suero","grupo":"Accesorios","valor":"Acero inoxidable, 15 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 5\" (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño externo: 810×490×960 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Trendelenburg: 0-12°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"USFDA, CE, ISO, SFDA"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Maternidad y puerperio","Observación neonatal","Unidades de cuidado del recién nacido","Traslado intradepartamental con frenos"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Maternity and postpartum care","Neonatal observation","Newborn care units","Intradepartmental transfer with brakes"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Lavabo acrílico transparente no tóxico, esterilizable a más de 100 °C para higiene y visibilidad.","Marco de acero inoxidable Baosteel con dimensiones externas 810 × 490 × 960 mm.","Porta suero de acero inoxidable de 15 kg y cuatro ruedas de 5\" (dos con freno).","Trendelenburg mecánico y colchón personalizado suave, antibacteriano y fácil de limpiar."],"beneficios_en":["Clear non-toxic acrylic bassinet, sterilizable above 100 °C for hygiene and visibility.","Baosteel stainless-steel frame with external dimensions 810 × 490 × 960 mm.","15 kg stainless-steel IV pole and four 5\" casters (two with brakes).","Mechanical Trendelenburg and a custom soft, antibacterial, easy-to-clean mattress."],"valor_es":"Una cuna neonatal hospitalaria con lavabo acrílico esterilizable y marco Baosteel, según la ficha oficial Saikang.","valor_en":"A hospital neonatal crib with sterilizable acrylic bassinet and Baosteel frame, per the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Cuáles son las dimensiones de la X01?","a":"Dimensiones externas 810 × 490 × 960 mm, según la ficha técnica."},{"q":"¿De qué material es el lavabo?","a":"Acrílico transparente no tóxico, esterilizable a temperaturas superiores a 100 °C."},{"q":"¿Qué carga admite el porta suero?","a":"El porta suero de acero inoxidable admite hasta 15 kg."},{"q":"¿Dónde descargo la ficha técnica de Cuna Neonatal X01?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are the X01 dimensions?","a":"External dimensions 810 × 490 × 960 mm, per the datasheet."},{"q":"What is the bassinet made of?","a":"Clear non-toxic acrylic, sterilizable at temperatures above 100 °C."},{"q":"What load does the IV pole support?","a":"The stainless-steel IV pole supports up to 15 kg."},{"q":"Where can I download the Neonatal Crib X01 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cuna neonatal hospitalaria","cuna de bebé X01 Saikang","cuna neonatal Colombia","cuna maternidad hospital","cuna acrílico transparente","mobiliario neonatal Saikang","ficha técnica X01 Saikang"],"seo_keywords_en":["hospital neonatal crib","X01 Saikang baby crib","neonatal crib Colombia","maternity hospital crib","clear acrylic baby bassinet","Saikang neonatal furniture","X01 Saikang datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/X01_Baby-Crib_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'cuna-neonatal-x01-ref-sk-a3-x01-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb039d-stretcher-trolley-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla para ambulancia hospitalaria Saikang SKB039(D) está pensada para el traslado seguro de pacientes en servicios de emergencia y ambulancias en Colombia. Su estructura de aleación de aluminio combina ligereza con la resistencia que exige el uso intensivo, y el ajuste de respaldo de 0 a 70° permite acomodar al paciente durante el transporte.

Soporta hasta 160 kg y viene con colchón de esponja ignífuga de 5 cm (30 kg/m³), dos cinturones de seguridad y ruedas silenciosas de 5" con freno universal de protección avanzada para mover y bloquear con facilidad.

El tapizado en cuero a prueba de llama, resistente al amarilleo y a los hongos, facilita la limpieza entre servicios —una ventaja operativa real para flotas de traslado.$d$,
  descripcion_larga_en = $d$The Saikang SKB039(D) ambulance stretcher is built for safe patient transfer in emergency services and ambulances in Colombia. Its aluminium-alloy structure combines lightness with the strength intensive use demands, and the 0–70° backrest adjustment lets crews position the patient during transport.

It supports up to 160 kg and comes with a 5 cm fire-retardant sponge mattress (30 kg/m³), two safety belts and quiet 5" casters with an advanced universal brake for easy movement and locking.

Flame-resistant leather upholstery that resists yellowing and mildew simplifies cleaning between runs —a real operational advantage for transfer fleets.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB039(D)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 160 kg"},{"clave":"Respaldo","grupo":"Ajustes","valor":"0-70°"},{"clave":"Estructura","grupo":"Material","valor":"Aleación de aluminio"},{"clave":"Colchón","grupo":"Material","valor":"Esponja ignífuga de 5 cm, 30 kg/m³"},{"clave":"Cinturones","grupo":"Seguridad","valor":"2"},{"clave":"Ruedas","grupo":"Ruedas","valor":"5\" silenciosas con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 160 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"2 cinturones de seguridad"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Barandilla lateral abatible"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colchón ignífugo 5 cm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Espuma 30 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas silenciosas 5\" con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resistente fuego, decoloración, moho"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Ambulancias y traslado prehospitalario","Servicios de urgencias","Traslado entre áreas hospitalarias","Flotas de evacuación"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Ambulances and prehospital transfer","Emergency departments","Inter-area hospital transfer","Evacuation fleets"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Estructura de aleación de aluminio con capacidad de carga ≤ 160 kg.","Respaldo ajustable de 0 a 70° para acomodar al paciente en traslado.","Colchón de esponja ignífuga de 5 cm (30 kg/m³) y dos cinturones de seguridad.","Ruedas silenciosas de 5\" con freno universal de protección avanzada."],"beneficios_en":["Aluminium-alloy frame with load capacity ≤ 160 kg.","Backrest adjustable from 0 to 70° to position the patient in transfer.","5 cm fire-retardant sponge mattress (30 kg/m³) and two safety belts.","Quiet 5\" casters with advanced universal brake protection."],"valor_es":"Una camilla de ambulancia de aluminio con respaldo 0–70° y carga ≤ 160 kg, según la ficha oficial Saikang.","valor_en":"An aluminium ambulance stretcher with 0–70° backrest and ≤ 160 kg load, per the official Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga admite la SKB039(D)?","a":"Capacidad de carga ≤ 160 kg, según la ficha técnica."},{"q":"¿Hasta qué ángulo ajusta el respaldo?","a":"El respaldo se ajusta de 0 a 70°."},{"q":"¿Qué incluye el colchón?","a":"Esponja ignífuga de 5 cm con densidad de 30 kg/m³, más dos cinturones de seguridad."},{"q":"¿Dónde descargo la ficha técnica de Camilla para Ambulancia SKB039(D)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What load does the SKB039(D) support?","a":"Load capacity ≤ 160 kg, per the datasheet."},{"q":"What backrest angle range does it have?","a":"The backrest adjusts from 0 to 70°."},{"q":"What does the mattress include?","a":"A 5 cm fire-retardant sponge at 30 kg/m³, plus two safety belts."},{"q":"Where can I download the Ambulance Stretcher SKB039(D) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla para ambulancia hospitalaria","camilla ambulancia SKB039D Saikang","camilla de emergencia Colombia","camilla aluminio ambulancia","stretcher trolley ambulancia","camilla traslado pacientes","ficha técnica SKB039D"],"seo_keywords_en":["ambulance stretcher trolley","SKB039D Saikang ambulance stretcher","emergency stretcher Colombia","aluminium ambulance stretcher","patient transfer stretcher","ambulance trolley Saikang","SKB039D datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB039D_Stretcher-Trolley_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-para-ambulancia-skb039-d-ref-skb039d-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb037c-patient-trolley-saikangmedical.pdf',
  descripcion_larga_es = $d$La camilla para pacientes hospitalaria Saikang SKB037(C) es un trolley de 1970 × 760 × 620–900 mm con carga segura de 200 kg, ideal para traslado y atención en pasillos y servicios de Colombia. Tres manivelas controlan respaldo (0–75°) y apoyo de rodillas (0–35°), dando al personal control manual preciso sin depender de motores.

El marco de acero inoxidable con acabado espejo, la superficie de tablero fenólico compacto (más delgada y apta para rayos X) y los rieles laterales de aleación de aluminio aportan higiene y acceso clínico. Ruedas cubiertas de 5" con freno universal y banda protectora remachada refuerzan la seguridad en movimiento.

De serie incluye dos porta sueros, soporte de oxígeno, plato de residuos y colchón: un paquete completo para la rutina de traslado intradepartamental.$d$,
  descripcion_larga_en = $d$The Saikang SKB037(C) patient trolley is a hospital stretcher at 1970 × 760 × 620–900 mm with a 200 kg safe working load, ideal for transfer and care in corridors and wards in Colombia. Three cranks control backrest (0–75°) and knee support (0–35°), giving staff precise manual control without motors.

A stainless-steel frame with mirror finish, phenolic compact-board surface (thinner and X-ray friendly) and aluminium-alloy side rails support hygiene and clinical access. Covered 5" casters with universal brake and a riveted bumper strip reinforce safety in motion.

It ships with two IV poles, oxygen bottle holder, debris plate and mattress: a complete package for intradepartmental transfer routines.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB037(C)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1970 x 760 x 620-900 mm"},{"clave":"Carga segura","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / rodillas","grupo":"Ajustes","valor":"0-75° / 0-35°"},{"clave":"Accionamiento","grupo":"Operación","valor":"3 manivelas"},{"clave":"Incluye","grupo":"Accesorios","valor":"2 porta sueros, soporte de oxígeno, plato de residuos, colchón"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 620-880 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 200 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie tablero fenólico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Marco acero inoxidable"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Traslado intradepartamental","Urgencias y observación","Procedimientos con acceso a rayos X","Hospitalización general"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Intradepartmental transfer","Emergency and observation","Procedures needing X-ray access","General inpatient care"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Carga segura de 200 kg con altura de 620 a 900 mm y tres manivelas de control.","Respaldo 0–75° y rodillas 0–35° para reposicionar al paciente en el traslado.","Superficie fenólica compacta apta para rayos X y marco de acero inoxidable pulido.","Incluye 2 porta sueros, soporte de oxígeno, plato de residuos y colchón."],"beneficios_en":["200 kg safe working load with height from 620 to 900 mm and three control cranks.","Backrest 0–75° and knees 0–35° to reposition the patient during transfer.","X-ray-friendly phenolic compact surface and mirror-polished stainless-steel frame.","Includes 2 IV poles, oxygen holder, debris plate and mattress."],"valor_es":"Una camilla de pacientes de 200 kg con tres manivelas y superficie apta para rayos X, según la ficha Saikang.","valor_en":"A 200 kg patient trolley with three cranks and an X-ray-friendly surface, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga segura tiene la SKB037(C)?","a":"Carga de trabajo segura de 200 kg."},{"q":"¿Cómo se operan los ajustes?","a":"Con tres manivelas: respaldo 0–75° y apoyo de rodillas 0–35°, más altura."},{"q":"¿La superficie permite rayos X?","a":"Sí: la superficie es de tablero fenólico compacto, más delgada y más fácil para radiografía, según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Camilla para Pacientes SKB037(C)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What safe working load does the SKB037(C) have?","a":"Safe working load of 200 kg."},{"q":"How are the adjustments operated?","a":"With three cranks: backrest 0–75° and knee support 0–35°, plus height."},{"q":"Is the surface X-ray compatible?","a":"Yes: the surface is phenolic compact board, thinner and easier for X-ray, per the datasheet."},{"q":"Where can I download the Patient Stretcher SKB037(C) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla para pacientes hospitalaria","camilla SKB037C Saikang","trolley de pacientes Colombia","camilla hospitalaria manivelas","camilla traslado rayos X","camilla acero inoxidable hospital","ficha técnica SKB037C"],"seo_keywords_en":["hospital patient trolley","SKB037C Saikang stretcher","patient trolley Colombia","manual crank hospital stretcher","X-ray compatible stretcher","stainless steel patient trolley","SKB037C datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB037C_Patient-Trolley_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-para-pacientes-skb037-c-ref-skb037c-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skr-at625-1-anesthesia-trolley-saikangmedical-1.pdf',
  descripcion_larga_es = $d$El carro de anestesia hospitalario Saikang SKR-AT625-1 organiza medicamentos e insumos en quirófano y salas de procedimiento en Colombia. Mide 620 × 475 × 945 mm (altura al tablero) y combina estructura de acero y ABS con cuatro columnas portantes para un puesto de trabajo estable y móvil.

Dos cajones (alturas de panel 80 mm y 120 mm) con separadores 3×3 libres y placa-nombre transparentes, cerradura de control central, gabinete, banco auxiliar extraíble y caja de almacenamiento a la izquierda, más contenedor rotatorio de cortopunzantes de 3 L y cubo de residuos ABS a la derecha, ordenan el flujo de trabajo anestésico.

El tablero antideslizante con barandillas de acero inoxidable 304 y vidrio blando transparente, la bandeja de anestesia de una fila con cinco cajas para medicamentos y las ruedas de 4" (dos con freno) completan un carro listo para la rutina perioperatoria.$d$,
  descripcion_larga_en = $d$The Saikang SKR-AT625-1 anesthesia trolley organizes medicines and supplies in operating rooms and procedure suites in Colombia. It measures 620 × 475 × 945 mm (height to tabletop) and combines a steel and ABS structure with four load-bearing columns for a stable, mobile workstation.

Two drawers (panel heights 80 mm and 120 mm) with free 3×3 partitions and transparent nameplates, central control lock, cabinet body, left-side pull-out auxiliary workbench and storage box, plus a rotatable 3 L sharps container and ABS waste bucket on the right, keep the anesthetic workflow ordered.

An anti-slip recessed tabletop with 304 stainless-steel guardrails and transparent soft glass, a single-row anesthesia rack with five medicine boxes and 4" casters (two with brakes) complete a cart ready for perioperative routines.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKR-AT625-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones","grupo":"Dimensiones","valor":"620 x 475 x 945 mm (altura al tablero)"},{"clave":"Estructura","grupo":"Material","valor":"Acero y plástico ABS, cuatro columnas portantes"},{"clave":"Cajones","grupo":"Configuración","valor":"2, con separadores 3x3 libres"},{"clave":"Cortopunzantes","grupo":"Configuración","valor":"Contenedor rotatorio de 3 L"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4\", 2 con freno"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño total: 620×475×945 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón superior: 80 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón mediano: 120 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones internas: 420×370 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas 4\""}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Quirófanos y salas de recuperación","Procedimientos con anestesia","Organización de medicamentos perioperatorios","Áreas de procedimientos menores"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Operating and recovery rooms","Anesthesia procedures","Perioperative medication organization","Minor procedure areas"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Estructura acero/ABS con cuatro columnas y tablero antideslizante con barandillas AISI 304.","Dos cajones con separadores 3×3 libres, cerradura central y gabinete para insumos.","Contenedor rotatorio de cortopunzantes de 3 L y cubo de residuos ABS de dos colores.","Banco auxiliar extraíble, rack de anestesia con 5 cajas y ruedas de 4\" (2 con freno)."],"beneficios_en":["Steel/ABS structure with four columns and anti-slip tabletop with 304 stainless guardrails.","Two drawers with free 3×3 partitions, central lock and cabinet for supplies.","Rotatable 3 L sharps container and two-color ABS waste bucket.","Pull-out auxiliary workbench, anesthesia rack with 5 boxes and 4\" casters (2 braked)."],"valor_es":"Un carro de anestesia compacto con cajones organizados, cortopunzantes de 3 L y tablero AISI 304, según ficha Saikang.","valor_en":"A compact anesthesia trolley with organized drawers, 3 L sharps container and 304 tabletop rails, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene el carro?","a":"620 × 475 × 945 mm (±10 mm) de altura al tablero."},{"q":"¿Cuántos cajones incluye?","a":"Dos cajones (paneles de 80 mm y 120 mm) con separadores 3×3 libres."},{"q":"¿Incluye contenedor de cortopunzantes?","a":"Sí: contenedor circular rotatorio de 3 L en el lado derecho."},{"q":"¿Dónde descargo la ficha técnica de Carro de Anestesia SKR-AT625-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are the cart dimensions?","a":"620 × 475 × 945 mm (±10 mm) height to tabletop."},{"q":"How many drawers does it include?","a":"Two drawers (80 mm and 120 mm panels) with free 3×3 partitions."},{"q":"Does it include a sharps container?","a":"Yes: a rotatable 3 L circular sharps container on the right side."},{"q":"Where can I download the Anesthesia Cart SKR-AT625-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["carro de anestesia hospitalario","carro anestesia SKR-AT625-1","carro de medicamentos quirófano","trolley anestesia Colombia","carro hospitalario ABS acero","carro cortopunzantes 3 litros","ficha técnica SKR-AT625-1"],"seo_keywords_en":["hospital anesthesia trolley","SKR-AT625-1 anesthesia cart","operating room medicine cart","anesthesia trolley Colombia","ABS steel hospital trolley","3 litre sharps cart","SKR-AT625-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKR-AT625-1_Anesthesia-Trolley_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'carro-de-anestesia-skr-ref-at625-1-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske011-1-treat-waiting-chair-saikangmedical.pdf',
  descripcion_larga_es = $d$La silla de espera hospitalaria 3 plazas Saikang SKE011-1 (1630 × 665 × 850 mm) aporta asientos ergonómicos para salas de espera clínicas y hospitalarias en Colombia. Asiento y respaldo de poliuretano de alta densidad (≥ 380 kg/m³) con estructura interna de acero Q235 resisten el uso prolongado sin deformarse con facilidad.

Los apoyabrazos de aluminio fundido y el diseño integral del asiento facilitan la limpieza diaria. Con asiento de 520 mm de ancho, 460 mm de fondo y 430 mm de altura al piso, y un peso de 52,5 kg por módulo, ofrece presencia estable en vestíbulos de alto tráfico.

Es una solución de mobiliario de espera pensada para confort duradero y mantenimiento sencillo —exactamente lo que buscan compras hospitalarias.$d$,
  descripcion_larga_en = $d$The Saikang SKE011-1 waiting chair (3-seater, 1630 × 665 × 850 mm) provides ergonomic seating for clinical and hospital waiting rooms in Colombia. High-density polyurethane seat and back (≥ 380 kg/m³) with an internal Q235 steel frame resist prolonged use without easy deformation.

Cast aluminium armrests and a one-piece seat design simplify daily cleaning. With a 520 mm seat width, 460 mm depth and 430 mm height from the floor, and a 52.5 kg module weight, it feels stable in high-traffic lobbies.

It is waiting furniture built for durable comfort and simple maintenance —exactly what hospital purchasing teams look for.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE011-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones (3 plazas)","grupo":"Dimensiones","valor":"1630 x 665 x 850 mm"},{"clave":"Asiento","grupo":"Dimensiones","valor":"520 mm ancho x 460 mm fondo x 430 mm altura"},{"clave":"Asiento y respaldo","grupo":"Material","valor":"Poliuretano de alta densidad, ≥ 380 kg/m³"},{"clave":"Estructura","grupo":"Material","valor":"Tubo de acero Q235; apoyabrazos de aluminio fundido"},{"clave":"Peso","grupo":"Peso","valor":"52,5 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Respaldo ≥23 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento ≥25 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"PU alta densidad"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero Q235"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño monopieza"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Salas de espera hospitalarias","Consultorios y clínicas","Vestíbulos de alto tráfico","Áreas de admisión"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Hospital waiting rooms","Clinics and consulting suites","High-traffic lobbies","Admission areas"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Módulo de 3 plazas 1630 × 665 × 850 mm con asiento ergonómico antideformación.","Poliuretano de alta densidad ≥ 380 kg/m³ con marco interno de acero Q235.","Apoyabrazos de aluminio fundido y superficie fácil de limpiar.","Asiento 520 × 460 mm a 430 mm del piso; peso del módulo 52,5 kg."],"beneficios_en":["3-seater module 1630 × 665 × 850 mm with ergonomic anti-deformation seating.","High-density polyurethane ≥ 380 kg/m³ with internal Q235 steel frame.","Cast aluminium armrests and easy-to-clean surface.","520 × 460 mm seat at 430 mm from floor; module weight 52.5 kg."],"valor_es":"Una banca de espera de 3 plazas en PU de alta densidad para vestíbulos clínicos, según ficha Saikang.","valor_en":"A 3-seater high-density PU waiting bench for clinical lobbies, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene la SKE011-1 de 3 plazas?","a":"1630 × 665 × 850 mm (±10 mm)."},{"q":"¿De qué material son asiento y respaldo?","a":"Poliuretano de alta densidad ≥ 380 kg/m³ con marco de acero Q235."},{"q":"¿Cuánto pesa el módulo?","a":"52,5 kg por módulo (roll), según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Silla de Espera SKE011-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are the 3-seater SKE011-1 dimensions?","a":"1630 × 665 × 850 mm (±10 mm)."},{"q":"What are the seat and back made of?","a":"High-density polyurethane ≥ 380 kg/m³ with a Q235 steel frame."},{"q":"How much does the module weigh?","a":"52.5 kg per module (roll), per the datasheet."},{"q":"Where can I download the Waiting Chair SKE011-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["silla de espera hospitalaria 3 plazas","banca de espera SKE011-1 Saikang","silla espera clínica Colombia","mobiliario sala de espera hospital","asiento poliuretano hospitalario","banca 3 puestos clínica","ficha técnica SKE011-1"],"seo_keywords_en":["3-seater hospital waiting chair","SKE011-1 Saikang waiting bench","clinical waiting chair Colombia","hospital waiting room furniture","polyurethane hospital seating","3-seat clinic bench","SKE011-1 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE011-1_Treat-waiting-Chair_saikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-espera-ref-ske011-1-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske942-recliner-chairs-for-elderly-saikang.pdf',
  descripcion_larga_es = $d$El sillón reclinable hospitalario Saikang SKE942 (1205 × 668 × 1180 mm) está pensado para diálisis, toma de muestras, cuidados respiratorios y cardíacos, y atención a adultos mayores en instituciones colombianas. Sus cuatro secciones (espalda, cadera, piernas y pies) con ajuste manual del respaldo (37°–61°) y reposapiernas (13°–36°) ofrecen tres modos: sentado, semirrecostado y recostado.

La bandeja de 650 × 390 mm con instalación tipo plug-in y cinco posiciones ayuda a adaptar el apoyo a cada paciente. Ruedas de 5" con freno y carga segura de 113 kg facilitan mover y fijar el sillón en sala.

Tapizado en cuero PU (rojo, verde o azul) y diseño ergonómico con reposapiés ocultable en modo sentado reducen riesgos de golpe y mejoran la experiencia del paciente en procedimientos prolongados.$d$,
  descripcion_larga_en = $d$The Saikang SKE942 recliner (1205 × 668 × 1180 mm) is designed for dialysis, blood collection, respiratory and cardiac care, and elderly care in Colombian facilities. Its four sections (back, hip, legs and feet) with manual backrest (37°–61°) and leg-rest (13°–36°) adjustment offer three modes: sitting, semi-reclining and lying.

The 650 × 390 mm tray with plug-in installation and five positions helps adapt support to each patient. 5" braked casters and a 113 kg safe working load make it easy to move and secure the chair in the room.

PU leather upholstery (red, green or blue) and an ergonomic design with a fully hidden footrest in sitting mode reduce knock risks and improve comfort during longer procedures.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE942"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1205 x 668 x 1180 mm"},{"clave":"Asiento / mesa","grupo":"Dimensiones","valor":"530 x 500 x 520 mm / 650 x 390 mm"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"37°-61° / 13°-36°"},{"clave":"Carga segura","grupo":"Capacidad","valor":"113 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU; rojo, verde o azul"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 secciones"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Unidades de diálisis","Toma de muestras y flebotomía","Cuidados respiratorios y cardíacos","Atención a adultos mayores"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Dialysis units","Blood collection and phlebotomy","Respiratory and cardiac care","Elderly care settings"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cuatro secciones con modos sentado, semirrecostado y recostado; carga segura 113 kg.","Respaldo 37°–61° y reposapiernas 13°–36° con reposapiés ocultable al sentarse.","Bandeja 650 × 390 mm con cinco posiciones de ajuste tipo plug-in.","Ruedas de 5\" con freno y tapizado PU en rojo, verde o azul."],"beneficios_en":["Four sections with sitting, semi-reclining and lying modes; 113 kg safe working load.","Backrest 37°–61° and leg-rest 13°–36° with footrest hidden when sitting.","650 × 390 mm tray with five plug-in adjustment positions.","5\" braked casters and PU leather in red, green or blue."],"valor_es":"Un sillón reclinable de 113 kg para diálisis y toma de muestras, con bandeja multiposición, según ficha Saikang.","valor_en":"A 113 kg recliner for dialysis and blood collection with a multi-position tray, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga segura tiene el SKE942?","a":"Carga de trabajo segura de 113 kg."},{"q":"¿Para qué usos indica la ficha el sillón?","a":"Diálisis, extracción de sangre, cuidados respiratorios y cardíacos, adaptándose a las necesidades del paciente."},{"q":"¿Qué rangos de ajuste tiene?","a":"Respaldo 37°–61° y reposapiernas 13°–36°."},{"q":"¿Dónde descargo la ficha técnica de Sillón Reclinable SKE942?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What safe working load does the SKE942 have?","a":"Safe working load of 113 kg."},{"q":"What uses does the datasheet indicate?","a":"Dialysis, blood collection, respiratory and cardiac care, adapting to patient needs."},{"q":"What adjustment ranges does it have?","a":"Backrest 37°–61° and leg-rest 13°–36°."},{"q":"Where can I download the Recliner Chair SKE942 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["sillón reclinable hospitalario","sillón diálisis SKE942 Saikang","silla reclinable toma de muestras","recliner hospitalario Colombia","sillón adultos mayores hospital","silla reclinable con bandeja","ficha técnica SKE942"],"seo_keywords_en":["hospital recliner chair","SKE942 Saikang dialysis recliner","blood collection recliner","hospital recliner Colombia","elderly care recliner chair","recliner with tray table","SKE942 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE942_Recliner-Chairs-for-Elderly_Saikang.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'sillon-reclinable-ref-ske942-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb039h-stretcher-trolley-saikangmedical-1.pdf',
  descripcion_larga_es = $d$La camilla transportadora ambulancia Saikang SKB039(H) está diseñada para carga y descarga en ambulancias con un solo operador. Desplegada mide 1950 × 570 × 910 mm y plegada 2030 × 570 × 300 mm; ofrece tres alturas (78, 87 y 91 cm), respaldo 0–75°, piernas 0–15° y carga ≤ 220 kg.

Patas en H, superficie separable con dispositivo de bloqueo, estructura de aleación de aluminio y acero inoxidable, ruedas de 6" (dos con freno), correas de pecho y pierna, colchón de esponja engrosada impermeable PVC de 100 mm y porta suero telescópico (hasta 71 cm) componen un sistema de traslado robusto.

Es una solución de alto rendimiento para flotas que necesitan plegado compacto, bloqueo de fijación y operación por un solo miembro del equipo.$d$,
  descripcion_larga_en = $d$The Saikang SKB039(H) stretcher trolley is designed for ambulance loading and unloading by a single operator. Unfolded it measures 1950 × 570 × 910 mm and folded 2030 × 570 × 300 mm; it offers three heights (78, 87 and 91 cm), backrest 0–75°, legs 0–15° and load ≤ 220 kg.

H-shaped legs, a separable surface with locking device, aluminium-alloy and stainless-steel structure, 6" casters (two braked), chest and leg straps, a 100 mm thickened waterproof PVC sponge mattress and a telescopic IV rack (up to 71 cm) form a robust transfer system.

It is a high-performance option for fleets that need compact folding, fixation locking and one-person operation.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB039(H)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"1950 x 570 x 910 mm / 2030 x 570 x 300 mm"},{"clave":"Alturas","grupo":"Ajustes","valor":"78, 87 y 91 cm"},{"clave":"Respaldo / piernas","grupo":"Ajustes","valor":"0-75° / 0-15°"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 220 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 6\" (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio alta resistencia"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Carga máxima: 180 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura 3 etapas"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Sistema suspensión compliant"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Carga y descarga en ambulancias","Traslado prehospitalario","Evacuación de emergencia","Servicios de urgencias"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Ambulance loading and unloading","Prehospital transfer","Emergency evacuation","Emergency departments"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Carga ≤ 220 kg con operación por un solo miembro del equipo.","Tres alturas (78/87/91 cm), respaldo 0–75° y piernas 0–15°.","Superficie separable con bloqueo; patas en H de aluminio/acero inoxidable.","Colchón PVC impermeable de 100 mm, correas pecho/pierna y porta suero telescópico."],"beneficios_en":["Load ≤ 220 kg with single-operator use.","Three heights (78/87/91 cm), backrest 0–75° and legs 0–15°.","Separable surface with lock; H-shaped aluminium/stainless-steel legs.","100 mm waterproof PVC mattress, chest/leg straps and telescopic IV rack."],"valor_es":"Una camilla de ambulancia ≤ 220 kg operable por una persona, con tres alturas y colchón de 100 mm, según ficha Saikang.","valor_en":"A ≤ 220 kg ambulance stretcher operable by one person, with three heights and a 100 mm mattress, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga admite la SKB039(H)?","a":"Capacidad de carga ≤ 220 kg."},{"q":"¿Cuántas personas se necesitan para operarla?","a":"La ficha indica que se requiere un miembro del equipo para operarla."},{"q":"¿Qué alturas ofrece?","a":"78 cm, 87 cm y 91 cm."},{"q":"¿Dónde descargo la ficha técnica de Camilla Transportadora SKB039(H)?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What load does the SKB039(H) support?","a":"Load capacity ≤ 220 kg."},{"q":"How many people are needed to operate it?","a":"The datasheet states one staff member is required to operate it."},{"q":"What heights does it offer?","a":"78 cm, 87 cm and 91 cm."},{"q":"Where can I download the Transport Stretcher SKB039(H) datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla transportadora ambulancia","camilla SKB039H Saikang","camilla ambulancia plegable Colombia","stretcher trolley 220 kg","camilla carga un operador","camilla aluminio ambulancia","ficha técnica SKB039H"],"seo_keywords_en":["ambulance stretcher trolley","SKB039H Saikang stretcher","folding ambulance stretcher Colombia","220 kg stretcher trolley","single operator ambulance stretcher","aluminium ambulance stretcher","SKB039H datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB039H_Stretcher-Trolley_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-transportadora-ref-skb039-h-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske020-1-es-foot-step-saikangmedical-es.pdf',
  descripcion_larga_es = $d$El taburete escalera hospitalario Saikang SKE020-1 (L490 × A405 × H170–340 mm) es un apoyo de dos peldaños para que pacientes y personal suban o bajen con más seguridad junto a camas y camillas en hospitales de Colombia. Su estructura de acero inoxidable con superficie superior de ABS de alta calidad combina higiene y firmeza.

Cuatro cubiertas antideslizantes fijas en los pies mejoran el agarre al piso —un detalle pequeño que reduce resbalones en áreas clínicas húmedas o de alto tráfico.

Compacto y fácil de ubicar en habitación o pasillo, es el accesorio de apoyo que completa el mobiliario de hospitalización sin ocupar espacio innecesario.$d$,
  descripcion_larga_en = $d$The Saikang SKE020-1 foot step (L490 × W405 × H170–340 mm) is a two-step stool that helps patients and staff step up or down more safely beside beds and stretchers in Colombian hospitals. Its stainless-steel structure with a high-quality ABS top surface combines hygiene and firmness.

Four fixed non-slip foot covers improve floor grip —a small detail that reduces slips in wet or high-traffic clinical areas.

Compact and easy to place in a room or corridor, it is the support accessory that completes inpatient furniture without wasting space.$d$,
