UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb3a104-soft-stretcher-saikangmedical-1.pdf',
  descripcion_larga_es = $d$La camilla blanda de rescate Saikang SKB3A104 está hecha para terreno difícil y traslados largos en Colombia: se despliega a 1800 × 670 mm y se pliega a 500 × 270 mm para caber en una bolsa de transporte. Su tela Oxford de doble capa engrosada soporta hasta 159 kg con diez asas (ocho perimetrales y dos en los extremos) reforzadas con tubo plástico.

Dos correas de seguridad en pecho y piernas estabilizan al paciente durante el movimiento. El formato blando permite pasar por espacios estrechos donde una camilla rígida no cabe.

Es la opción ligera y plegable que equipos de rescate y emergencias necesitan cuando el peso y el volumen importan tanto como la capacidad de carga.$d$,
  descripcion_larga_en = $d$The Saikang SKB3A104 soft stretcher is built for difficult-terrain rescue and long-distance transfers in Colombia: it unfolds to 1800 × 670 mm and folds to 500 × 270 mm to fit in a carry bag. Thickened double-layer Oxford cloth supports up to 159 kg with ten handles (eight around the perimeter and two at the ends) reinforced with plastic tubing.

Two safety straps at chest and legs stabilize the patient in motion. The soft format can pass through tight spaces where a rigid stretcher cannot.

It is the light, foldable option rescue and emergency teams need when weight and bulk matter as much as load capacity.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB3A104"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"1800 x 670 mm / 500 x 270 mm"},{"clave":"Material","grupo":"Material","valor":"Tela Oxford de doble capa"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Asas / correas","grupo":"Configuración","valor":"10 con tubo plástico / 2"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones desplegada: 1800×650 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones plegada: 440×280×50 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: ≤159 kg"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Rescate en montaña y terreno irregular","Transporte a larga distancia","Evacuación en espacios estrechos","Equipos de emergencias"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Mountain and rough-terrain rescue","Long-distance transportation","Evacuation in tight spaces","Emergency response teams"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Tela Oxford de doble capa con carga ≤ 159 kg.","Diez asas con tubo plástico para rescate y transporte largo.","Se pliega a 500 × 270 mm y guarda en bolsa de transporte.","Dos correas de seguridad en pecho y piernas."],"beneficios_en":["Double-layer Oxford cloth with load ≤ 159 kg.","Ten plastic-tubed handles for rescue and long transport.","Folds to 500 × 270 mm and stores in a tote bag.","Two safety straps at chest and legs."],"valor_es":"Una camilla blanda plegable ≤ 159 kg con 10 asas para rescate y traslado largo, según ficha Saikang.","valor_en":"A foldable soft stretcher ≤ 159 kg with 10 handles for rescue and long transfer, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga admite la SKB3A104?","a":"Capacidad de carga ≤ 159 kg."},{"q":"¿Cuántas asas tiene?","a":"Diez asas: ocho alrededor y dos en los extremos, con tubo plástico."},{"q":"¿Para qué usos la indica la ficha?","a":"Rescate en montaña y transporte a larga distancia."},{"q":"¿Dónde descargo la ficha técnica de Camilla Blanda SKB3A104?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What load does the SKB3A104 support?","a":"Load capacity ≤ 159 kg."},{"q":"How many handles does it have?","a":"Ten handles: eight around and two at the ends, with plastic tubing."},{"q":"What uses does the datasheet indicate?","a":"Mountain rescue and long-distance transportation."},{"q":"Where can I download the Soft Stretcher SKB3A104 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["camilla blanda de rescate","camilla flexible SKB3A104 Saikang","camilla Oxford plegable Colombia","camilla rescate montaña","soft stretcher hospitalario","camilla emergencia tela","ficha técnica SKB3A104"],"seo_keywords_en":["soft rescue stretcher","SKB3A104 Saikang soft stretcher","foldable Oxford stretcher Colombia","mountain rescue stretcher","soft stretcher emergency","fabric emergency stretcher","SKB3A104 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB3A104_Soft-Stretcher_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
