UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skh046-2-overbed-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesa de cama hospitalaria ajustable Saikang SKH046-2 (890 × 445 × 760–1050 mm) acerca comida, lectura o dispositivos al paciente sin forzar posturas incómodas. El sistema de resorte de gas ajusta la altura de la cubierta con suavidad, y el tablero de ABS facilita la limpieza diaria en habitaciones hospitalarias de Colombia.

El marco de acero al carbono pulverizado y cuatro ruedas de goma giratorias aportan estabilidad y movilidad entre camas. Es un accesorio de sobrecama pensado para enfermería y confort del paciente en hospitalización.

Compacta, rodante y de altura variable: exactamente el tipo de mobiliario auxiliar que agiliza la rutina de piso.$d$,
  descripcion_larga_en = $d$The Saikang SKH046-2 overbed table (890 × 445 × 760–1050 mm) brings meals, reading or devices closer to the patient without awkward postures. A gas-spring system raises and lowers the tabletop smoothly, and the ABS board simplifies daily cleaning in Colombian hospital rooms.

A powder-coated carbon-steel frame and four swivel rubber casters add stability and mobility between beds. It is an overbed accessory built for nursing workflow and patient comfort on the ward.

Compact, rolling and height-adjustable: exactly the auxiliary furniture that speeds floor routines.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKH046-2"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"890 x 445 x (760-1050) mm"},{"clave":"Tablero","grupo":"Material","valor":"ABS"},{"clave":"Marco","grupo":"Material","valor":"Acero al carbono pulverizado"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de goma giratorias"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 770-1050 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 ruedas goma"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero recubrimiento polvo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Materiales ABS y acero"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie HDPE"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones de hospitalización","Apoyo para comidas en cama","Uso de dispositivos junto al paciente","Pisos de enfermería"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient rooms","In-bed meal support","Device use at the bedside","Nursing floors"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura ajustable 760–1050 mm con resorte de gas.","Tablero ABS fácil de limpiar sobre marco de acero al carbono pulverizado.","Cuatro ruedas de goma giratorias para mover la mesa entre camas.","Formato 890 × 445 mm ideal como mesa de sobrecama."],"beneficios_en":["Height adjustable 760–1050 mm with gas spring.","Easy-clean ABS top on powder-coated carbon-steel frame.","Four swivel rubber casters to move the table between beds.","890 × 445 mm format ideal as an overbed table."],"valor_es":"Una mesa de sobrecama con altura a gas 760–1050 mm y tablero ABS, según ficha Saikang.","valor_en":"An overbed table with gas height 760–1050 mm and ABS top, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué rango de altura tiene la SKH046-2?","a":"De 760 a 1050 mm, con ajuste por resorte de gas."},{"q":"¿De qué material es el tablero?","a":"Tablero de ABS; marco de acero al carbono pulverizado."},{"q":"¿Tiene ruedas?","a":"Sí: cuatro ruedas de goma giratorias."},{"q":"¿Dónde descargo la ficha técnica de Mesita de Noche SKH046-2?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What height range does the SKH046-2 have?","a":"From 760 to 1050 mm, with gas-spring adjustment."},{"q":"What is the tabletop made of?","a":"ABS board; powder-coated carbon-steel frame."},{"q":"Does it have casters?","a":"Yes: four swivel rubber casters."},{"q":"Where can I download the Nightstand SKH046-2 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesa de cama hospitalaria ajustable","mesa sobrecama SKH046-2 Saikang","mesa de cama Colombia","mesa hospitalaria con ruedas","mobiliario habitación hospital","overbed table hospitalaria","ficha técnica SKH046-2"],"seo_keywords_en":["adjustable hospital overbed table","SKH046-2 Saikang overbed table","hospital bed table Colombia","rolling hospital table","inpatient room furniture","medical overbed table","SKH046-2 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKH046-2_Overbed-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
