UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks009-2-phenolic-resin-bedside-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesita de noche hospitalaria fenólica Saikang SKS009-2 (510 × 480 × 750 mm, mesa de comedor hasta 950 mm) organiza pertenencias del paciente con un cajón, un gabinete, espacio abierto intermedio y tablero de escritura lateral. El cuerpo fenólico con tratamiento redondeado es antiácido, antiálcali, impermeable, fácil de limpiar e ignífugo durante 4 horas según la ficha.

Ruedas médicas silenciosas de doble cara (dos con freno bloqueable a 360°) y pistas deslizantes silenciosas mejoran el movimiento y el uso diario. El mango de aleación de aluminio anodizado y la barandilla superior de acero inoxidable completan un mueble de habitación resistente.

Es la mesita de noche hospitalaria que combina almacenamiento, superficie de apoyo y movilidad silenciosa para pisos de hospitalización en Colombia.$d$,
  descripcion_larga_en = $d$The Saikang SKS009-2 phenolic compact bedside cabinet (510 × 480 × 750 mm, dining board up to 950 mm) organizes patient belongings with one drawer, one cabinet, an open mid space and a side writing board. The rounded phenolic body is acid- and alkali-resistant, waterproof, easy to clean and fire-resistant for 4 hours per the datasheet.

Quiet dual medical casters (two with 360° lockable brakes) and quiet slide tracks improve daily movement and use. An anodized aluminium-alloy handle and stainless-steel top rail complete a durable room cabinet.

It is the hospital bedside table that combines storage, support surface and quiet mobility for inpatient floors in Colombia.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS009-2"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"510 x 480 x 750 mm"},{"clave":"Altura máxima mesa de comedor","grupo":"Dimensiones","valor":"950 mm"},{"clave":"Cuerpo","grupo":"Material","valor":"Tablero fenólico compacto"},{"clave":"Contenido","grupo":"Configuración","valor":"1 cajón, 1 gabinete, 4 ruedas, tablero de escritura lateral"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tablero fenólico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resistente ácidos/álcalis"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cajón amortiguación silenciosa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Mesa escritura plegable"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones de hospitalización","Almacenamiento de pertenencias del paciente","Apoyo para comidas junto a la cama","Pisos de enfermería"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient rooms","Patient belongings storage","Bedside meal support","Nursing floors"]$j$::jsonb)),
