a fenólica","mesilla SKS009-2 Saikang","mesa de noche hospital Colombia","mobiliario habitación fenólico","mesita paciente con ruedas","bedside table hospitalaria","ficha técnica SKS009-2"],"seo_keywords_en":["phenolic hospital bedside table","SKS009-2 Saikang bedside cabinet","hospital nightstand Colombia","phenolic inpatient furniture","rolling patient bedside table","hospital bedside cabinet","SKS009-2 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS009-2_Phenolic-Resin-Bedside-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
