UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb1a01-foldable-stretcher-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla plegable de emergencia Saikang SKB1A01 (4 pliegues) es ligera —solo 6 kg netos— y se despliega a 2100 × 500 × 100 mm o se guarda en 580 × 220 × 210 mm. Estructura de aleación de aluminio y tela Oxford ignífuga de alta resistencia (resistente al moho y al desgaste 100.000 ciclos) soportan una carga de trabajo de 159 kg.

Su diseño ergonómico y operación simple la hacen práctica para evacuación de emergencia en hospitales, seguridad escolar, hoteles y atención a personas mayores, según indica la ficha.

Cuando el equipo necesita una camilla compacta que cabe en un vehículo o depósito sin sacrificar capacidad, la SKB1A01 es una respuesta clara y documentada.$d$,
  descripcion_larga_en = $d$The Saikang SKB1A01 folding stretcher (4 folds) is light —only 6 kg net— and unfolds to 2100 × 500 × 100 mm or stores at 580 × 220 × 210 mm. An aluminium-alloy frame and high-strength fire-retardant Oxford cloth (mildew-resistant and wear-tested to 100,000 cycles) support a 159 kg working load.

Its ergonomic design and simple operation make it practical for emergency evacuation in hospitals, school safety, hotels and elderly care, as the datasheet indicates.

When teams need a compact stretcher that fits in a vehicle or storeroom without sacrificing capacity, the SKB1A01 is a clear, documented answer.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB1A01"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"2100 x 500 x 100 mm / 580 x 220 x 210 mm"},{"clave":"Carga de trabajo","grupo":"Capacidad","valor":"159 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"6 kg"},{"clave":"Estructura / tela","grupo":"Material","valor":"Aleación de aluminio / Oxford ignífugo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio alta resistencia"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tela impermeable lona"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegable en largo y ancho"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Evacuación de emergencia en hospitales","Seguridad escolar y hoteles","Atención a personas mayores","Traslado ligero en campo"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Hospital emergency evacuation","School and hotel safety","Elderly care transfer","Light field transfer"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Solo 6 kg netos con carga de trabajo 159 kg.","4 pliegues: 2100 × 500 × 100 mm desplegada / 580 × 220 × 210 mm plegada.","Aleación de aluminio y Oxford ignífugo resistente a 100.000 ciclos de desgaste.","Diseño ergonómico para evacuación en hospitales, escuelas y hoteles."],"beneficios_en":["Only 6 kg net with 159 kg working load.","4 folds: 2100 × 500 × 100 mm unfolded / 580 × 220 × 210 mm folded.","Aluminium alloy and fire-retardant Oxford rated to 100,000 wear cycles.","Ergonomic design for evacuation in hospitals, schools and hotels."],"valor_es":"Una camilla plegable de 6 kg y 159 kg de carga para evacuaciones, según ficha Saikang.","valor_en":"A 6 kg folding stretcher with 159 kg load for evacuations, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa la SKB1A01?","a":"Peso neto de 6 kg."},{"q":"¿Qué carga de trabajo admite?","a":"159 kg."},{"q":"¿Cómo se pliega?","a":"Es de 4 pliegues; plegada mide 580 × 220 × 210 mm."},{"q":"¿Dónde descargo la ficha técnica de Camilla Plegable SKB1A01?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does the SKB1A01 weigh?","a":"Net weight of 6 kg."},{"q":"What working load does it support?","a":"159 kg."},{"q":"How does it fold?","a":"It is a 4-fold design; folded size is 580 × 220 × 210 mm."},{"q":"Where can I download the Folding Stretcher SKB1A01 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla plegable de emergencia","camilla SKB1A01 Saikang","camilla aluminio plegable Colombia","camilla evacuación hospital","camilla ligera 6 kg","stretcher plegable emergencia","ficha técnica SKB1A01"],"seo_keywords_en":["folding emergency stretcher","SKB1A01 Saikang folding stretcher","aluminium folding stretcher Colombia","hospital evacuation stretcher","lightweight 6 kg stretcher","portable emergency stretcher","SKB1A01 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB1A01__Foldable-Stretcher_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
