UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske001-19-attendant-sofa-saikangmedical.pdf',
  descripcion_larga_es = $d$El sofá de acompañante hospitalario Saikang SKE001-19 convierte el descanso del acompañante en una superficie más larga: 1600 × 700 × 655 mm plegado y 2200 × 700 × 655 mm extendido (extensión 300 mm), con carga de 250 kg. Tapizado en cuero PU con relleno de esponja de 40 kg/m³ y base de tubo de acero > 1,5 mm con recubrimiento electrostático.

Diseño ergonómico de uso sencillo y aspecto premium para habitaciones donde la familia permanece muchas horas. El ancho de apoyabrazos de 100 mm aporta apoyo lateral cómodo.

Es el sofá-cama de acompañante que equilibran compras hospitalarias cuando buscan durabilidad, carga alta y extensión real documentada en ficha.$d$,
  descripcion_larga_en = $d$The Saikang SKE001-19 attendant sofa turns companion rest into a longer surface: 1600 × 700 × 655 mm folded and 2200 × 700 × 655 mm extended (300 mm extension), with a 250 kg load. PU leather upholstery with 40 kg/m³ sponge fill and a > 1.5 mm steel-tube base with electrostatic coating.

An easy-to-use ergonomic, high-end design for rooms where families stay for many hours. 100 mm armrest width adds comfortable side support.

It is the attendant sofa-bed hospital buyers balance when they want durability, high load and a real extension documented on the datasheet.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE001-19"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Plegado / extendido","grupo":"Dimensiones","valor":"1600 x 700 x 655 mm / 2200 x 700 x 655 mm"},{"clave":"Carga","grupo":"Capacidad","valor":"250 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU, relleno de esponja de 40 kg/m³"},{"clave":"Base","grupo":"Material","valor":"Tubo de acero > 1,5 mm con recubrimiento electrostático"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegado: 1600×700×655 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Desplegado: 2200×700×655 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Extensión: 300 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Reposabrazos: 100 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: 250 kg"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones con acompañante","Hospitalización general","Descanso nocturno de familiares","Suites de paciente"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Rooms with companions","General inpatient care","Overnight family rest","Patient suites"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Extensión de 300 mm: 1600 mm plegado / 2200 mm extendido.","Carga de 250 kg para uso intensivo de acompañantes.","Cuero PU con esponja 40 kg/m³ y base de acero > 1,5 mm.","Diseño ergonómico con apoyabrazos de 100 mm."],"beneficios_en":["300 mm extension: 1600 mm folded / 2200 mm extended.","250 kg load for intensive attendant use.","PU leather with 40 kg/m³ sponge and > 1.5 mm steel base.","Ergonomic design with 100 mm armrests."],"valor_es":"Un sofá de acompañante extensible de 250 kg para habitaciones hospitalarias, según ficha Saikang.","valor_en":"A 250 kg extendable attendant sofa for hospital rooms, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga admite el SKE001-19?","a":"Carga de 250 kg."},{"q":"¿Cuánto se extiende?","a":"Distancia de extensión 300 mm; de 1600 mm plegado a 2200 mm extendido."},{"q":"¿De qué está tapizado?","a":"Cuero PU con relleno de esponja de 40 kg/m³."},{"q":"¿Dónde descargo la ficha técnica de Sofá de Asistente SKE001-19?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What load does the SKE001-19 support?","a":"Loading of 250 kg."},{"q":"How far does it extend?","a":"Extension distance 300 mm; from 1600 mm folded to 2200 mm unfolded."},{"q":"What is the upholstery?","a":"PU leather with 40 kg/m³ sponge fill."},{"q":"Where can I download the Assistant Sofa SKE001-19 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["sofá de acompañante hospitalario","sofá asistente SKE001-19 Saikang","sofá cama acompañante Colombia","mobiliario habitación familiar hospital","sofá hospitalario extensible","attendant sofa hospitalario","ficha técnica SKE001-19"],"seo_keywords_en":["hospital attendant sofa","SKE001-19 Saikang attendant sofa","hospital companion sofa bed Colombia","family inpatient room furniture","extendable hospital sofa","medical attendant sofa","SKE001-19 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE001-19_Attendant-Sofa_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'sofa-de-asistente-ref-ske001-19-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske011-treat-waiting-chair-saikangmedical.pdf',
  descripcion_larga_es = $d$La silla de espera clínica 3 plazas Saikang SKE011 (1770 × 605 × 845 mm con apoyabrazos) ofrece asiento y respaldo de poliuretano moldeado en una pieza, resistentes a aceite, envejecimiento, hongos y abrasión, con propiedades ecológicas no tóxicas según la ficha. Asiento de 520 × 450 mm a 440 mm del piso y peso de 52,5 kg por módulo.

Apoyabrazos y patas de aleación de aluminio fundido con recubrimiento electrostático; patas tipo palo de golf y pads antideslizantes ocultos que agarran el piso sin ruido. El diseño ergonómico busca evitar deformación por sedestación prolongada.

Ideal para salas de espera clínicas y hospitalarias en Colombia que necesitan presencia sólida, limpieza sencilla y confort diario.$d$,
  descripcion_larga_en = $d$The Saikang SKE011 waiting chair (3-seater with armrests, 1770 × 605 × 845 mm) offers a one-piece moulded polyurethane seat and back that resist oil, aging, mould and abrasion, with eco-friendly non-toxic properties per the datasheet. Seat 520 × 450 mm at 440 mm from the floor and 52.5 kg module weight.

Cast aluminium-alloy armrests and legs with electrostatic coating; golf-club-shaped legs and hidden non-slip pads that grip the floor quietly. The ergonomic design aims to prevent deformation from prolonged sitting.

Ideal for clinical and hospital waiting rooms in Colombia that need solid presence, easy cleaning and everyday comfort.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE011"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones (3 plazas con apoyabrazos)","grupo":"Dimensiones","valor":"1770 x 605 x 845 mm"},{"clave":"Asiento","grupo":"Dimensiones","valor":"520 mm ancho x 450 mm fondo x 440 mm altura"},{"clave":"Asiento y respaldo","grupo":"Material","valor":"Poliuretano (PU) moldeado en una pieza"},{"clave":"Peso","grupo":"Peso","valor":"52,5 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento y respaldo PU moldeado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ancho asiento: 520 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura acero 1.2 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capacidad: 250 kg"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Salas de espera clínicas","Hospitales y centros de salud","Áreas de admisión","Vestíbulos institucionales"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Clinical waiting rooms","Hospitals and health centres","Admission areas","Institutional lobbies"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["3 plazas 1770 × 605 × 845 mm con PU moldeado en una pieza.","Resistencia a aceite, hongos y abrasión; peso del módulo 52,5 kg.","Apoyabrazos y patas de aluminio fundido con pads antideslizantes ocultos.","Diseño ergonómico antideformación para espera prolongada."],"beneficios_en":["3-seater 1770 × 605 × 845 mm with one-piece moulded PU.","Oil, mould and abrasion resistance; module weight 52.5 kg.","Cast aluminium armrests and legs with hidden non-slip pads.","Ergonomic anti-deformation design for long waits."],"valor_es":"Una banca de espera de 3 plazas en PU moldeado con patas de aluminio, según ficha Saikang.","valor_en":"A 3-seater moulded-PU waiting bench with aluminium legs, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene la SKE011?","a":"1770 × 605 × 845 mm (±5 mm) en versión de 3 plazas con apoyabrazos."},{"q":"¿De qué material son asiento y respaldo?","a":"Poliuretano (PU) moldeado en una pieza."},{"q":"¿Cuánto pesa?","a":"52,5 kg por módulo."},{"q":"¿Dónde descargo la ficha técnica de Silla de Espera SKE011?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are the SKE011 dimensions?","a":"1770 × 605 × 845 mm (±5 mm) for the 3-seater with armrests."},{"q":"What are the seat and back made of?","a":"One-piece moulded polyurethane (PU)."},{"q":"How much does it weigh?","a":"52.5 kg per module."},{"q":"Where can I download the Waiting Chair SKE011 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["silla de espera clínica 3 plazas","banca espera SKE011 Saikang","silla espera hospital Colombia","mobiliario sala de espera PU","banca aluminio clínica","waiting chair hospitalaria","ficha técnica SKE011"],"seo_keywords_en":["3-seater clinical waiting chair","SKE011 Saikang waiting bench","hospital waiting chair Colombia","PU waiting room furniture","aluminium clinic waiting bench","medical waiting chair","SKE011 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE011_Treat-waiting-Chair_saikangmedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-espera-ref-ske011-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skh042-overbed-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesa de sobrecama hospitalaria Saikang SKH042 ofrece un tablero de 800 × 410 mm con elevación de altura de 730 a 1130 mm para acercar comida o actividades al paciente en hospitalización colombiana. El tablero de MDF con cubiertas laterales de PVC y el marco inferior de acero al carbono pulverizado aportan una base estable.

Cuatro ruedas de goma giratorias permiten desplazar la mesa entre camas con facilidad. Es un accesorio de sobrecama sencillo, robusto y fácil de integrar en la dotación de piso.

Cuando el servicio necesita una mesa de cama con amplio rango de altura y materiales claros en ficha, la SKH042 cumple sin complicaciones.$d$,
  descripcion_larga_en = $d$The Saikang SKH042 overbed table offers an 800 × 410 mm top with height lift from 730 to 1130 mm to bring meals or activities closer to inpatients in Colombia. An MDF top with PVC side covers and a powder-coated carbon-steel lower frame provide a stable base.

Four swivel rubber casters make it easy to move the table between beds. It is a simple, robust overbed accessory that fits floor inventories cleanly.

When a service needs an overbed table with a wide height range and clear datasheet materials, the SKH042 delivers without fuss.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKH042"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tablero","grupo":"Dimensiones","valor":"800 x 410 mm"},{"clave":"Altura","grupo":"Dimensiones","valor":"730 - 1130 mm"},{"clave":"Tablero / marco","grupo":"Material","valor":"MDF con cubiertas de PVC / acero al carbono"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de goma giratorias"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Resorte a gas"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ajuste altura: 770-1050 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 ruedas silenciosas 2\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"2 con freno"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones de hospitalización","Apoyo para comidas en cama","Actividades del paciente en cama","Pisos de enfermería"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient rooms","In-bed meal support","In-bed patient activities","Nursing floors"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Tablero 800 × 410 mm con altura 730–1130 mm.","MDF con cubiertas PVC y marco de acero al carbono pulverizado.","Cuatro ruedas de goma giratorias para movilidad.","Centro de gravedad estable para uso junto a la cama."],"beneficios_en":["800 × 410 mm top with height 730–1130 mm.","MDF with PVC covers and powder-coated carbon-steel frame.","Four swivel rubber casters for mobility.","Stable centre of gravity for bedside use."],"valor_es":"Una mesa de sobrecama 800 × 410 mm con altura 730–1130 mm, según ficha Saikang.","valor_en":"An 800 × 410 mm overbed table with 730–1130 mm height, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué tamaño tiene el tablero?","a":"800 × 410 mm."},{"q":"¿Cuál es el rango de altura?","a":"730 a 1130 mm."},{"q":"¿De qué materiales está hecha?","a":"Tablero MDF con cubiertas de PVC y marco de acero al carbono pulverizado."},{"q":"¿Dónde descargo la ficha técnica de Mesa de Sobrecama SKH042?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What size is the tabletop?","a":"800 × 410 mm."},{"q":"What is the height range?","a":"730 to 1130 mm."},{"q":"What materials is it made of?","a":"MDF top with PVC covers and powder-coated carbon-steel frame."},{"q":"Where can I download the Overbed Table SKH042 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["mesa de sobrecama hospitalaria","mesa de cama SKH042 Saikang","mesa hospitalaria ajustable Colombia","overbed table hospital","mesa paciente con ruedas","mobiliario cama hospitalaria","ficha técnica SKH042"],"seo_keywords_en":["hospital overbed table","SKH042 Saikang bed table","adjustable hospital table Colombia","medical overbed table","rolling patient bed table","hospital bedside table furniture","SKH042 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKH042_Overbed-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'mesa-de-sobrecama-ref-skh042-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skr-ib00-simple-laptop-cart-saikangmedical-es.pdf',
  descripcion_larga_es = $d$El carro para computador hospitalario Saikang SKR-IB00 (533 × 455 × 750–1150 mm) acerca el computador portátil al punto de atención en pisos de enfermería de Colombia. Tablero de ABS fácil de limpiar y resistente a rayones, columna de aleación de aluminio y base metálica cubierta de ABS aportan estabilidad y mantenimiento sencillo.

Incluye 1 cesta grande, 1 bandeja, soporte telescópico de ratón ambidiestro y compartimento con llave. Ruedas de doble cara silenciosas (2 delanteras con freno 360°). Opcional: batería de litio de alto rendimiento con luz LED para alimentación estable.

Es el carro de ABS que digitaliza la ronda clínica sin improvisar mesas ni cables sueltos.$d$,
  descripcion_larga_en = $d$The Saikang SKR-IB00 cart (533 × 455 × 750–1150 mm) brings the laptop to the point of care on Colombian nursing floors. An easy-clean scratch-resistant ABS top, aluminium-alloy column and metal base with ABS cover add stability and simple maintenance.

It includes 1 large basket, 1 tray, ambidextrous telescopic mouse support and a lockable compartment. Quiet dual casters (2 front brakes at 360°). Optional: high-performance lithium battery with LED light for stable power.

It is the ABS cart that digitizes clinical rounds without improvised tables or loose cables.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKR-IB00"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones","grupo":"Dimensiones","valor":"533 x 455 x 750-1150 mm"},{"clave":"Tablero / columna","grupo":"Material","valor":"ABS / aleación de aluminio"},{"clave":"Contenido","grupo":"Configuración","valor":"1 cesta grande, 1 bandeja, 4 ruedas"},{"clave":"Opcional","grupo":"Opcionales","valor":"Batería de litio con luz LED"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aluminio, acero, ABS"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Moldeo inyección ABS"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Reposabrazos"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Barandilla acero inoxidable 304"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Vidrio templado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tamaño: 750×475×920 mm"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Rondas de enfermería con portátil","Registro electrónico en piso","Punto de atención móvil","Áreas de hospitalización"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Nursing rounds with laptop","Electronic charting on the floor","Mobile point of care","Inpatient areas"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura 750–1150 mm con tablero ABS y columna de aluminio.","Cesta, bandeja, soporte de ratón ambidiestro y compartimento con llave.","Ruedas silenciosas con 2 frenos delanteros bloqueables a 360°.","Opcional: batería de litio con luz LED para alimentación móvil."],"beneficios_en":["Height 750–1150 mm with ABS top and aluminium column.","Basket, tray, ambidextrous mouse support and lockable compartment.","Quiet casters with 2 front brakes lockable at 360°.","Optional: lithium battery with LED light for mobile power."],"valor_es":"Un carro para portátil de ABS con altura 750–1150 mm y compartimento con llave, según ficha Saikang.","valor_en":"An ABS laptop cart with 750–1150 mm height and lockable compartment, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene el SKR-IB00?","a":"533 × 455 × 750–1150 mm."},{"q":"¿Qué incluye de serie?","a":"1 cesta grande, 1 bandeja y 4 ruedas; más soporte de ratón y compartimento con llave según configuración técnica."},{"q":"¿Hay opción de batería?","a":"Sí: batería de litio de alto rendimiento con luz LED, opcional."},{"q":"¿Dónde descargo la ficha técnica de Carro de ABS SKR-IB00?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are the SKR-IB00 dimensions?","a":"533 × 455 × 750–1150 mm."},{"q":"What is included as standard?","a":"1 large basket, 1 tray and 4 casters; plus mouse support and lockable compartment per the technical configuration."},{"q":"Is there a battery option?","a":"Yes: optional high-performance lithium battery with LED light."},{"q":"Where can I download the ABS Cart SKR-IB00 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["carro para computador hospitalario","carro portátil SKR-IB00 Saikang","carro enfermería computador Colombia","carro ABS hospitalario","trolley laptop clínico","carro punto de atención","ficha técnica SKR-IB00"],"seo_keywords_en":["hospital laptop cart","SKR-IB00 Saikang computer trolley","nursing laptop cart Colombia","ABS hospital computer cart","clinical laptop trolley","point of care cart","SKR-IB00 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKR-IB00_Simple-Laptop-Cart_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'carro-de-abs-skr-ref-ib00-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb2a10-spine-board-saikangmedical-1.pdf',
  descripcion_larga_es = $d$El tablero espinal de emergencia Saikang SKB2A10 (1380 × 350 × 50 mm) es equipo de transferencia en HDPE de alta resistencia, capaz de permitir fluoroscopia/rayos X durante el traslado según la ficha. Carga ≤ 159 kg, tres correas y respaldo elevable 0–60° para adaptar la posición del paciente.

Su formato rígido y materiales de ingeniería plástica facilitan la inmovilización y el movimiento coordinado del equipo de emergencias en Colombia.

Cuando el protocolo exige un spine board documentado —dimensiones, carga y compatibilidad con imagen— el SKB2A10 responde con datos claros de fabricante.$d$,
  descripcion_larga_en = $d$The Saikang SKB2A10 spine board (1380 × 350 × 50 mm) is high-strength HDPE emergency transfer equipment that can allow X-ray/fluoroscopy during transfer per the datasheet. Load ≤ 159 kg, three straps and a backrest raisable 0–60° to adapt patient position.

Its rigid format and engineering-plastic materials support immobilization and coordinated movement by emergency teams in Colombia.

When protocol requires a documented spine board —dimensions, load and imaging compatibility— the SKB2A10 answers with clear manufacturer data.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB2A10"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"1380 x 350 x 50 mm"},{"clave":"Material","grupo":"Material","valor":"HDPE"},{"clave":"Carga","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Correas / respaldo","grupo":"Configuración","valor":"3 / elevable 0-60°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"8 pasadores"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Translúcido rayos X"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Superficie lisa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Parte inferior convexa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Una pieza"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Impermeable fluidos corporales"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Transferencia de emergencia","Inmovilización en rescate","Urgencias y trauma","Traslado con necesidad de imagen"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Emergency transfer","Rescue immobilization","Emergency and trauma care","Transfer needing imaging"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["HDPE de alta resistencia, tamaño 1380 × 350 × 50 mm (±10 mm).","Carga ≤ 159 kg con tres correas de sujeción.","Respaldo elevable de 0 a 60°.","Apta para transferencia de emergencia con fluoroscopia/rayos X según ficha."],"beneficios_en":["High-strength HDPE, size 1380 × 350 × 50 mm (±10 mm).","Load ≤ 159 kg with three securing straps.","Backrest raisable from 0 to 60°.","Suitable for emergency transfer with X-ray/fluoroscopy per datasheet."],"valor_es":"Un tablero espinal HDPE ≤ 159 kg con respaldo 0–60° y compatibilidad de imagen, según ficha Saikang.","valor_en":"An HDPE spine board ≤ 159 kg with 0–60° backrest and imaging compatibility, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué tamaño tiene el SKB2A10?","a":"1380 × 350 × 50 mm (±10 mm)."},{"q":"¿Qué carga admite?","a":"≤ 159 kg."},{"q":"¿Permite rayos X?","a":"La ficha lo describe como equipo de transferencia de emergencia que puede realizar fluoroscopia/rayos X."},{"q":"¿Dónde descargo la ficha técnica de Tablero Espinal SKB2A10?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What size is the SKB2A10?","a":"1380 × 350 × 50 mm (±10 mm)."},{"q":"What load does it support?","a":"≤ 159 kg."},{"q":"Does it allow X-ray?","a":"The datasheet describes it as emergency transfer equipment that can perform X-ray/fluoroscopy."},{"q":"Where can I download the Spinal Board SKB2A10 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["tablero espinal de emergencia","spine board SKB2A10 Saikang","tabla espinal Colombia","tablero inmovilización HDPE","camilla rígida emergencia","spine board hospitalario","ficha técnica SKB2A10"],"seo_keywords_en":["emergency spine board","SKB2A10 Saikang spine board","spine board Colombia","HDPE immobilization board","rigid emergency backboard","hospital spine board","SKB2A10 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKB2A10_Spine-board_SaikangMedical-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
