UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/v2k-manual-bed-saikangmedical.pdf',
  descripcion_larga_es = $d$La cama manual hospitalaria Saikang V2k (2130 × 995 mm externos; plataforma 1925 × 900 mm) ofrece hospitalización robusta con carga segura de 200 kg y altura externa de 500 mm. Dos manivelas ajustan respaldo (0–70°) y apoyo de rodillas (0–38°) para reposicionar al paciente sin depender de motores.

Plataforma de PP con retenedor de colchón, extremos de PP con bloqueo seguro y ruedas parachoques Ø65, riel lateral plegable de aleación de aluminio con postes de acero inoxidable, ruedas cubiertas de 5", porta suero de 4 ganchos y ganchos de drenaje conforman un paquete clínico completo. Acero Baosteel con soldadura robótica Panasonic y plástico esterilizable a 100 °C respaldan la durabilidad.

Diseño aséptico sin costuras en cabecera, piecero y superficie para desinfección rápida: una cama manual pensada para control de infecciones en hospitales colombianos.$d$,
  descripcion_larga_en = $d$The Saikang V2k manual bed (2130 × 995 mm external; 1925 × 900 mm platform) delivers robust inpatient care with a 200 kg safe working load and 500 mm external height. Two cranks adjust backrest (0–70°) and knee support (0–38°) to reposition the patient without motors.

PP platform with mattress retainer, PP ends with safe lock and Ø65 bumper wheels, foldable aluminium-alloy side rail with stainless-steel poles, covered 5" casters, 4-hook IV pole and drainage hooks form a complete clinical package. Baosteel steel with Panasonic robotic welding and plastic sterilizable at 100 °C back durability.

Aseptic seamless design at head, foot and surface for quick disinfection: a manual bed built for infection control in Colombian hospitals.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"V2k"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"2130 x 995 mm"},{"clave":"Plataforma de colchón","grupo":"Dimensiones","valor":"1925 x 900 mm"},{"clave":"Carga segura","grupo":"Capacidad","valor":"200 kg"},{"clave":"Respaldo / rodillas","grupo":"Ajustes","valor":"0-70° / 0-38°"},{"clave":"Operación","grupo":"Configuración","valor":"2 manivelas"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 cubiertas de 5\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plataforma PP con retenedor"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cabecero/piecero PP"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas parachoques Φ65"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Opcional: retroceso, estante, trapecio"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Hospitalización general","Unidades con preferencia de cama manual","Control de infecciones en piso","Reposición de paciente con manivelas"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["General inpatient care","Units preferring manual beds","Floor infection control","Patient repositioning with cranks"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Carga segura 200 kg con 2 manivelas: respaldo 0–70° y rodillas 0–38°.","Plataforma PP con retenedor, extremos PP con bloqueo y riel de aluminio plegable.","Acero Baosteel con soldadura robótica y plástico esterilizable a 100 °C.","Porta suero 4 ganchos, ganchos de drenaje y ruedas cubiertas de 5\"."],"beneficios_en":["200 kg safe load with 2 cranks: backrest 0–70° and knees 0–38°.","PP platform with retainer, PP ends with lock and foldable aluminium rail.","Baosteel with robotic welding and plastic sterilizable at 100 °C.","4-hook IV pole, drainage hooks and covered 5\" casters."],"valor_es":"Una cama manual de 200 kg con plataforma PP lavable y acero Baosteel, según ficha Saikang.","valor_en":"A 200 kg manual bed with washable PP platform and Baosteel steel, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga segura tiene la V2k?","a":"Carga de trabajo segura de 200 kg."},{"q":"¿Cómo se ajusta?","a":"Con 2 manivelas: respaldo 0–70° (±10°) y rodillas 0–38°."},{"q":"¿Qué materiales destacan?","a":"Plataforma y extremos de PP, riel de aluminio, acero Baosteel y plástico esterilizable a 100 °C."},{"q":"¿Dónde descargo la ficha técnica de Camilla Manual V2k?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What safe working load does the V2k have?","a":"Safe working load of 200 kg."},{"q":"How is it adjusted?","a":"With 2 cranks: backrest 0–70° (±10°) and knees 0–38°."},{"q":"What materials stand out?","a":"PP platform and ends, aluminium rail, Baosteel steel and plastic sterilizable at 100 °C."},{"q":"Where can I download the Manual Stretcher V2k datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["cama manual hospitalaria","cama manual V2k Saikang","cama hospital 2 manivelas Colombia","cama PP lavable hospitalaria","cama Baosteel hospital","cama hospitalización manual","ficha técnica V2k Saikang"],"seo_keywords_en":["manual hospital bed","V2k Saikang manual bed","2-crank hospital bed Colombia","washable PP hospital bed","Baosteel hospital bed","manual inpatient bed","V2k Saikang datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/07/V2k_Manual-Bed_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-manual-v2k-ref-sk-c1-v2k-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skb1a02-foldable-stretcher-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La camilla transportadora plegable Saikang SKB1A02 (2 pliegues) equilibra capacidad y guardado: 2080 × 570 × 140 mm desplegada y 1040 × 180 × 90 mm plegada, con solo 6 kg netos y carga de trabajo ≤ 159 kg. Aleación de aluminio y tela Oxford ignífuga —resistente al moho y al desgaste 100.000 ciclos— la hacen ligera y durable.

Diseño ergonómico de estructura simple y alta seguridad para ancianos, seguridad escolar y evacuaciones en hospitales y hoteles, según la ficha.

Es la hermana de 2 pliegues de la línea SKB1A: más compacta al plegarse a lo largo, ideal cuando el espacio de almacenamiento es crítico.$d$,
  descripcion_larga_en = $d$The Saikang SKB1A02 folding stretcher (2 folds) balances capacity and storage: 2080 × 570 × 140 mm unfolded and 1040 × 180 × 90 mm folded, at only 6 kg net with working load ≤ 159 kg. Aluminium alloy and fire-retardant Oxford cloth —mildew-resistant and wear-tested to 100,000 cycles— keep it light and durable.

An ergonomic simple structure with high safety for the elderly, school safety and evacuations in hospitals and hotels, per the datasheet.

It is the 2-fold sibling in the SKB1A line: more compact when folded lengthwise, ideal when storage space is critical.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKB1A02"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Desplegada / plegada","grupo":"Dimensiones","valor":"2080 x 570 x 140 mm / 1040 x 180 x 90 mm"},{"clave":"Carga de trabajo","grupo":"Capacidad","valor":"≤ 159 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"6 kg"},{"clave":"Estructura / tela","grupo":"Material","valor":"Aleación de aluminio / Oxford ignífugo"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Aleación aluminio"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plegable en largo y ancho"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tela PVC ignífuga e impermeable"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Evacuación hospitalaria","Seguridad escolar y hotelera","Traslado de personas mayores","Respuesta de emergencia ligera"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Hospital evacuation","School and hotel safety","Elderly transfer","Light emergency response"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["2 pliegues: 2080 × 570 × 140 mm / 1040 × 180 × 90 mm.","Solo 6 kg netos con carga ≤ 159 kg.","Aluminio y Oxford ignífugo resistente a 100.000 ciclos.","Indicada para evacuación en hospitales, escuelas y hoteles."],"beneficios_en":["2 folds: 2080 × 570 × 140 mm / 1040 × 180 × 90 mm.","Only 6 kg net with load ≤ 159 kg.","Aluminium and fire-retardant Oxford rated to 100,000 cycles.","Indicated for evacuation in hospitals, schools and hotels."],"valor_es":"Una camilla plegable de 2 pliegues, 6 kg y ≤ 159 kg de carga, según ficha Saikang.","valor_en":"A 2-fold stretcher at 6 kg with ≤ 159 kg load, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿En qué se diferencia de la SKB1A01?","a":"La SKB1A02 es de 2 pliegues (la SKB1A01 es de 4); dimensiones y formato plegado difieren según cada ficha."},{"q":"¿Qué carga admite?","a":"Carga de trabajo ≤ 159 kg."},{"q":"¿Cuánto pesa?","a":"Peso neto 6 kg."},{"q":"¿Dónde descargo la ficha técnica de Camilla Transportadora SKB1A02?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"How does it differ from the SKB1A01?","a":"The SKB1A02 is 2-fold (SKB1A01 is 4-fold); dimensions and folded format differ per each datasheet."},{"q":"What load does it support?","a":"Working load ≤ 159 kg."},{"q":"How much does it weigh?","a":"Net weight 6 kg."},{"q":"Where can I download the Transport Stretcher SKB1A02 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["camilla transportadora plegable","camilla SKB1A02 Saikang","camilla aluminio 2 pliegues Colombia","camilla evacuación ligera","camilla emergencia 6 kg","folding stretcher hospitalaria","ficha técnica SKB1A02"],"seo_keywords_en":["folding transfer stretcher","SKB1A02 Saikang folding stretcher","2-fold aluminium stretcher Colombia","light evacuation stretcher","6 kg emergency stretcher","hospital folding stretcher","SKB1A02 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/10/SKB1A02_Foldable-Stretcher_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'camilla-transportadora-ref-skb1a02-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske001-attendant-chair-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La silla reclinable de acompañante Saikang SKE001 acompaña al familiar en habitación: 640 × 720 × 940 mm en posición sentada y 640 × 1900 × 420 mm en horizontal, con tapizado de cuero ignífugo. Puede retirarse/convertirse para uso como cama y hacer más cómoda la noche del acompañante, según la ficha.

Reposacabezas pensado para proteger vértebras cervicales, ruedas médicas silenciosas antiestáticas de 2" (×4) y 3" (×2), impermeables y antibacterianas, más fundas antideslizantes para pies de cama y almohada incluida.

Es la silla-cama de asistente compacta que muchas habitaciones colombianas necesitan cuando no cabe un sofá completo.$d$,
  descripcion_larga_en = $d$The Saikang SKE001 recliner accompanies family in the room: 640 × 720 × 940 mm seated and 640 × 1900 × 420 mm horizontal, with fire-retardant leather upholstery. It can be converted for bed use to make the attendant's night more comfortable, per the datasheet.

A headrest designed to protect cervical vertebrae, quiet antistatic medical casters of 2" (×4) and 3" (×2), waterproof and antibacterial, plus non-slip bed-foot covers and an included pillow.

It is the compact attendant recliner-bed many Colombian rooms need when a full sofa will not fit.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE001"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Sentada (L x A x A)","grupo":"Dimensiones","valor":"640 x 720 x 940 mm"},{"clave":"Horizontal (L x A x A)","grupo":"Dimensiones","valor":"640 x 1900 x 420 mm"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero ignífugo"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 de 2\" y 2 de 3\""},{"clave":"Característica","grupo":"Catálogo IME","valor":"Asiento: 640×720×940 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Cama: 640×1900×420 mm"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones con acompañante","Descanso nocturno familiar","Hospitalización general","Espacios reducidos de habitación"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Rooms with companions","Overnight family rest","General inpatient care","Compact patient rooms"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Pasa de sentada 640 × 720 × 940 mm a horizontal 640 × 1900 × 420 mm.","Cuero ignífugo y reposacabezas ergonómico para el cuello.","Ruedas silenciosas antiestáticas de 2\" y 3\", impermeables y antibacterianas.","Incluye almohada y fundas antideslizantes para pies de cama."],"beneficios_en":["Converts from seated 640 × 720 × 940 mm to horizontal 640 × 1900 × 420 mm.","Fire-retardant leather and ergonomic headrest for the neck.","Quiet antistatic 2\" and 3\" casters, waterproof and antibacterial.","Includes pillow and non-slip bed-foot covers."],"valor_es":"Una silla reclinable de acompañante que se convierte en cama 1900 mm, según ficha Saikang.","valor_en":"An attendant recliner that converts to a 1900 mm bed, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué medidas tiene sentada y horizontal?","a":"Sentada 640 × 720 × 940 mm; horizontal 640 × 1900 × 420 mm."},{"q":"¿Se puede usar como cama?","a":"Sí: la ficha indica que puede retirarse/convertirse para que los acompañantes nocturnos estén más cómodos."},{"q":"¿Qué ruedas trae?","a":"4 ruedas de 2\" y 2 de 3\", médicas silenciosas antiestáticas."},{"q":"¿Dónde descargo la ficha técnica de Silla de Asistente SKE001?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What are the seated and horizontal sizes?","a":"Seated 640 × 720 × 940 mm; horizontal 640 × 1900 × 420 mm."},{"q":"Can it be used as a bed?","a":"Yes: the datasheet states it can convert so overnight attendants are more comfortable."},{"q":"What casters does it have?","a":"4 casters of 2\" and 2 of 3\", quiet antistatic medical wheels."},{"q":"Where can I download the Assistant Chair SKE001 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["silla reclinable de acompañante","silla asistente SKE001 Saikang","silla cama acompañante Colombia","sillón familiar hospitalario","silla reclinable habitación hospital","attendant chair hospitalaria","ficha técnica SKE001"],"seo_keywords_en":["attendant recliner chair","SKE001 Saikang attendant chair","hospital companion chair bed Colombia","family hospital recliner","inpatient attendant recliner","medical attendant chair","SKE001 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE001_Attendant-Chair_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-asistente-ref-ske001-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/skp011-sectional-memory-foam-mattress-saikangmedical-fr.pdf',
  descripcion_larga_es = $d$El colchón viscoelástico hospitalario Saikang SKP011 de espuma con memoria seccional (1920 × 870 × 100 mm) combina una capa superior viscoelástica de 40 mm (42–45 kg/m³) con base de espuma de poliuretano (40 kg/m³) para apoyo y alivio de presión, según la ficha del fabricante (documento en francés).

La funda de PU con cremallera larga es impermeable, transpirable, suave y de alta resistencia a la tracción; se retira con facilidad para lavar. Se acepta tamaño personalizado y colores de funda gris o azul oscuro; la capa superior puede ser azul, verde o negra.

Es un colchón hospitalario de espuma de memoria documentado para instituciones en Colombia que buscan confort de superficie sin inventar indicaciones clínicas fuera de la ficha.$d$,
  descripcion_larga_en = $d$The Saikang SKP011 sectional memory-foam mattress (1920 × 870 × 100 mm) combines a 40 mm viscoelastic top layer (42–45 kg/m³) with a polyurethane foam base (40 kg/m³) for support and pressure relief, per the manufacturer datasheet (French document).

The PU zip cover is waterproof, breathable, soft and high in tensile strength; the long zipper design makes it easy to remove and wash. Custom sizing is acceptable; cover colours grey or dark blue; top layer may be blue, green or black.

It is a documented hospital memory-foam mattress for Colombian facilities seeking surface comfort without inventing clinical claims beyond the datasheet.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKP011"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"1920 x 870 x 100 mm"},{"clave":"Capa superior","grupo":"Material","valor":"Espuma viscoelástica, 40 mm, 42-45 kg/m³"},{"clave":"Base","grupo":"Material","valor":"Espuma de poliuretano, 40 kg/m³"},{"clave":"Funda","grupo":"Material","valor":"PU con cremallera, impermeable y transpirable"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Espuma viscoelástica 40 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Densidad: 42-45 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Capa base poliuretano 100 mm"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Densidad base: 40 kg/m³"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colores: azul, verde, negro"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Camas de hospitalización","Superficies de descanso clínico","Dotación de colchones institucionales","Habitaciones de paciente"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient beds","Clinical rest surfaces","Institutional mattress inventories","Patient rooms"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capa viscoelástica 40 mm (42–45 kg/m³) sobre base PU 40 kg/m³.","Formato 1920 × 870 × 100 mm; tamaño personalizado aceptable.","Funda PU con cremallera larga, impermeable y transpirable, lavable.","Propiedades termoactivas de la espuma de memoria para apoyo y alivio de presión (ficha)."],"beneficios_en":["40 mm viscoelastic layer (42–45 kg/m³) over 40 kg/m³ PU base.","1920 × 870 × 100 mm format; custom size acceptable.","PU long-zip cover, waterproof and breathable, washable.","Thermo-active memory-foam properties for support and pressure relief (datasheet)."],"valor_es":"Un colchón viscoelástico 1920 × 870 × 100 mm con funda PU lavable, según ficha Saikang.","valor_en":"A 1920 × 870 × 100 mm viscoelastic mattress with washable PU cover, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué dimensiones tiene el SKP011?","a":"1920 × 870 × 100 mm; la ficha indica que se acepta tamaño personalizado."},{"q":"¿Cómo está construido?","a":"Capa superior de espuma viscoelástica 40 mm (42–45 kg/m³) y base de espuma de poliuretano 40 kg/m³."},{"q":"¿La funda se puede lavar?","a":"Sí: funda PU con cremallera larga, fácil de retirar y lavar; impermeable y transpirable."},{"q":"¿Dónde descargo la ficha técnica de Colchón Viscoelástico SKP011?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en francés)."}],"preguntas_frecuentes_en":[{"q":"What are the SKP011 dimensions?","a":"1920 × 870 × 100 mm; the datasheet states custom size is acceptable."},{"q":"How is it built?","a":"40 mm viscoelastic top (42–45 kg/m³) and polyurethane foam base at 40 kg/m³."},{"q":"Can the cover be washed?","a":"Yes: PU cover with long zipper, easy to remove and wash; waterproof and breathable."},{"q":"Where can I download the Memory Foam Mattress SKP011 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in French)."}],"seo_keywords_es":["colchón viscoelástico hospitalario","colchón memoria SKP011 Saikang","colchón hospitalario Colombia","colchón espuma memoria clínica","colchón PU impermeable hospital","mattress viscoelástico cama hospital","ficha técnica SKP011"],"seo_keywords_en":["hospital viscoelastic mattress","SKP011 Saikang memory foam mattress","hospital mattress Colombia","clinical memory foam mattress","waterproof PU hospital mattress","viscoelastic hospital bed mattress","SKP011 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"fr","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKP011_Sectional-Memory-Foam-Mattress_SaikangMedical_FR.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'colchon-viscoelastico-ref-skp011-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks036-bedside-table-saikangmedical.pdf',
  descripcion_larga_es = $d$La mesa de noche hospitalaria acero Saikang SKS036 (440 × 440 × 790 mm) aporta almacenamiento compacto en habitación con gabinete de acero laminado en frío de primer grado y encimera de acero inoxidable 304 de 0,7 mm. Cada cajón admite hasta 35 kg; cuatro ruedas universales (2 delanteras con freno) soportan 100 kg de carga en ruedas.

Paneles de cajón y puerta con acabado limpio para el entorno clínico. Es un bedside table metálico pensado para durar en el uso intensivo de pisos hospitalarios en Colombia.

Dimensiones contenidas, materiales explícitos en ficha y movilidad con freno: una mesita de noche sin adornos innecesarios.$d$,
  descripcion_larga_en = $d$The Saikang SKS036 bedside table (440 × 440 × 790 mm) brings compact room storage with a first-grade cold-rolled steel cabinet and 0.7 mm 304 stainless-steel top. Each drawer holds up to 35 kg; four universal casters (2 front braked) support 100 kg caster load.

Drawer and door panels with a clean finish for the clinical environment. It is a metal bedside table built to last under intensive use on Colombian hospital floors.

Contained dimensions, datasheet-explicit materials and braked mobility: a nightstand without unnecessary frills.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS036"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Tamaño","grupo":"Dimensiones","valor":"440 x 440 x 790 mm"},{"clave":"Gabinete / tablero","grupo":"Material","valor":"Acero laminado en frío / acero inoxidable 304 (0,7 mm)"},{"clave":"Carga por cajón","grupo":"Capacidad","valor":"35 kg"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 universales, 2 delanteras con freno; carga 100 kg"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Dimensiones: 440×440×790 mm"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones de hospitalización","Almacenamiento compacto del paciente","Pisos con preferencia de mobiliario metálico","Dotación institucional"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient rooms","Compact patient storage","Floors preferring metal furniture","Institutional inventories"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Formato compacto 440 × 440 × 790 mm.","Gabinete de acero laminado en frío y tablero AISI 304 de 0,7 mm.","Carga por cajón 35 kg.","4 ruedas universales (2 con freno) con carga de ruedas 100 kg."],"beneficios_en":["Compact 440 × 440 × 790 mm format.","Cold-rolled steel cabinet and 0.7 mm 304 stainless top.","35 kg load per drawer.","4 universal casters (2 braked) with 100 kg caster load."],"valor_es":"Una mesa de noche de acero 440 mm con tablero 304 y cajones de 35 kg, según ficha Saikang.","valor_en":"A 440 mm steel bedside table with 304 top and 35 kg drawers, per Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué tamaño tiene la SKS036?","a":"440 × 440 × 790 mm."},{"q":"¿De qué material es la encimera?","a":"Acero inoxidable 304 de 0,7 mm."},{"q":"¿Qué carga admite cada cajón?","a":"35 kg por cajón."},{"q":"¿Dónde descargo la ficha técnica de Mesa de Noche SKS036?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What size is the SKS036?","a":"440 × 440 × 790 mm."},{"q":"What is the top made of?","a":"0.7 mm 304 stainless steel."},{"q":"What load does each drawer support?","a":"35 kg per drawer."},{"q":"Where can I download the Night Table SKS036 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in English)."}],"seo_keywords_es":["mesa de noche hospitalaria acero","mesita SKS036 Saikang","mesa de noche inoxidable Colombia","bedside table hospital acero","mobiliario habitación metálico","mesita paciente con freno","ficha técnica SKS036"],"seo_keywords_en":["steel hospital bedside table","SKS036 Saikang nightstand","stainless bedside table Colombia","hospital steel bedside cabinet","metal inpatient room furniture","braked patient nightstand","SKS036 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"en","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS036_Bedside-Table_SaikangMedical.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'mesa-de-noche-ref-sks036-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/x01-1-baby-crib-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La cuna neonatal ajustable hospitalaria Saikang X01-1 (880 × 520 × 770–940 mm) suma a la línea de cunas el ajuste de altura y Trendelenburg/inverso 0–12° (±4°) mediante manivela y resortes de gas. Lavabo transparente de acrílico no tóxico, esterilizable a más de 100 °C, y ruedas de caucho Φ100 mm / 4" (2 con freno) giratorias 360°.

Tres colores opcionales (azul, verde, rosa) ayudan a identificar áreas o preferencias de servicio. Diseño moderno y ergonómico orientado a la comodidad del bebé en maternidad y neonatología colombianas.

Frente a la X01 fija, la X01-1 aporta rango de altura y Trendelenburg documentados para equipos que necesitan más flexibilidad postural.$d$,
  descripcion_larga_en = $d$The Saikang X01-1 neonatal crib (880 × 520 × 770–940 mm) adds height adjustment and Trendelenburg/reverse 0–12° (±4°) via crank and gas springs to the hospital crib line. Clear non-toxic acrylic bassinet, sterilizable above 100 °C, and Φ100 mm / 4" rubber casters (2 braked) that swivel 360°.

Three optional colours (blue, green, pink) help identify areas or service preferences. A modern ergonomic design oriented to infant comfort in Colombian maternity and neonatology.

Versus the fixed X01, the X01-1 brings documented height range and Trendelenburg for teams that need more postural flexibility.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"X01-1"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"880 x 520 x 770-940 mm"},{"clave":"Trendelenburg / inverso","grupo":"Ajustes","valor":"0-12° (±4°)"},{"clave":"Lavabo","grupo":"Material","valor":"Acrílico transparente no tóxico, esterilizable > 100 °C"},{"clave":"Ruedas","grupo":"Ruedas","valor":"4 giratorias de Φ100 mm (2 con freno)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colchón personalizado"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas sin goma 360°"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Colores: azul, verde, rosa"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Plástico ecológico no tóxico"},{"clave":"Característica","grupo":"Catálogo IME","valor":"USFDA, CE, ISO, SFDA"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Maternidad y neonatología","Cuidado del recién nacido con inclinación","Habitaciones de puerperio","Unidades que requieren altura variable"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Maternity and neonatology","Newborn care with tilt","Postpartum rooms","Units needing variable height"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Altura 770–940 mm con manivela y resortes de gas.","Trendelenburg e inverso 0–12° (±4°).","Lavabo acrílico no tóxico esterilizable > 100 °C.","Ruedas de caucho 4\" / Φ100 mm (2 con freno); colores azul, verde o rosa."],"beneficios_en":["Height 770–940 mm with crank and gas springs.","Trendelenburg and reverse 0–12° (±4°).","Non-toxic acrylic bassinet sterilizable > 100 °C.","4\" / Φ100 mm rubber casters (2 braked); blue, green or pink colours."],"valor_es":"Una cuna neonatal con altura ajustable y Trendelenburg 0–12°, según ficha Saikang.","valor_en":"A neonatal crib with adjustable height and 0–12° Trendelenburg, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué rango de altura tiene la X01-1?","a":"770 a 940 mm (±10 mm) en dimensiones externas 880 × 520 mm."},{"q":"¿Ofrece Trendelenburg?","a":"Sí: Trendelenburg e inverso de 0 a 12° (±4°)."},{"q":"¿Qué colores hay?","a":"Azul, verde o rosa, opcionales según ficha."},{"q":"¿Dónde descargo la ficha técnica de Cuna Neonatal X01-1?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What height range does the X01-1 have?","a":"770 to 940 mm (±10 mm) at external footprint 880 × 520 mm."},{"q":"Does it offer Trendelenburg?","a":"Yes: Trendelenburg and reverse from 0 to 12° (±4°)."},{"q":"What colours are available?","a":"Blue, green or pink, optional per the datasheet."},{"q":"Where can I download the Neonatal Crib X01-1 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["cuna neonatal ajustable hospitalaria","cuna bebé X01-1 Saikang","cuna neonatal Trendelenburg Colombia","cuna maternidad altura ajustable","cuna acrílico hospitalaria","mobiliario neonatal ajustable","ficha técnica X01-1 Saikang"],"seo_keywords_en":["adjustable hospital neonatal crib","X01-1 Saikang baby crib","Trendelenburg neonatal crib Colombia","adjustable height maternity crib","acrylic hospital baby crib","adjustable neonatal furniture","X01-1 Saikang datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/X01-1_Baby-Crib_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'cuna-neonatal-x01-1-ref-sk-ad3-x01-1-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/ske941-recliner-chairs-for-elderly-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La silla reclinable para diálisis Saikang SKE941 (1100 × 770 × 1280 mm) está indicada en ficha para diálisis, extracción de sangre y cuidados respiratorios y cardíacos. Cuatro secciones (espalda, cadera, piernas y pies) con ajuste neumático del respaldo (37°–61°) y reposapiernas (13°–36°); tres modos: sentado, semirrecostado y recostado, con reposapiés oculto al sentarse para evitar golpes.

Asiento 540 × 460 × 560 mm, bandeja 480 × 255 mm y carga segura 113 kg. Tapizado en cuero PU ignífugo de 1,2 mm (rojo, verde o azul) sobre espuma moldeada.

Es el sillón de procedimientos que equipos de nefrología y toma de muestras en Colombia eligen cuando necesitan reclinado neumático documentado y bandeja integrada.$d$,
  descripcion_larga_en = $d$The Saikang SKE941 recliner (1100 × 770 × 1280 mm) is datasheet-indicated for dialysis, blood collection and respiratory and cardiac care. Four sections (back, hip, legs and feet) with pneumatic backrest (37°–61°) and leg-rest (13°–36°); three modes: sitting, semi-reclining and reclining, with the footrest hidden when sitting to avoid knocks.

Seat 540 × 460 × 560 mm, tray 480 × 255 mm and safe working load 113 kg. 1.2 mm fire-retardant PU leather (red, green or blue) over moulded foam.

It is the procedure recliner nephrology and phlebotomy teams in Colombia choose when they need documented pneumatic recline and an integrated tray.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKE941"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"1100 x 770 x 1280 mm"},{"clave":"Respaldo / reposapiernas","grupo":"Ajustes","valor":"37°-61° / 13°-36°"},{"clave":"Carga segura","grupo":"Capacidad","valor":"113 kg"},{"clave":"Tapizado","grupo":"Material","valor":"Cuero PU ignífugo de 1,2 mm; rojo, verde o azul"},{"clave":"Característica","grupo":"Catálogo IME","valor":"4 secciones (respaldo, cadera, pierna, pie)"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Diseño ergonómico"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Unidades de diálisis","Toma de muestras","Cuidados respiratorios y cardíacos","Atención a adultos mayores"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Dialysis units","Blood collection","Respiratory and cardiac care","Elderly care"]$j$::jsonb)),
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Ajuste neumático: respaldo 37°–61° y reposapiernas 13°–36°.","Tres modos con reposapiés ocultable; carga segura 113 kg.","Bandeja 480 × 255 mm e asiento 540 × 460 × 560 mm.","Cuero PU ignífugo 1,2 mm en rojo, verde o azul."],"beneficios_en":["Pneumatic adjustment: backrest 37°–61° and leg-rest 13°–36°.","Three modes with hideable footrest; 113 kg safe working load.","480 × 255 mm tray and 540 × 460 × 560 mm seat.","1.2 mm fire-retardant PU leather in red, green or blue."],"valor_es":"Una silla reclinable neumática de 113 kg para diálisis y toma de muestras, según ficha Saikang.","valor_en":"A 113 kg pneumatic recliner for dialysis and blood collection, per the Saikang datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué carga segura tiene la SKE941?","a":"113 kg."},{"q":"¿El ajuste del respaldo es neumático?","a":"Sí: la ficha describe ajuste neumático del respaldo con tres modos."},{"q":"¿Para qué usos la indica el fabricante?","a":"Diálisis, extracción de sangre, cuidados respiratorios y cardíacos."},{"q":"¿Dónde descargo la ficha técnica de Silla Reclinable SKE941?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Saikang Medical (en español)."}],"preguntas_frecuentes_en":[{"q":"What safe working load does the SKE941 have?","a":"113 kg."},{"q":"Is the backrest adjustment pneumatic?","a":"Yes: the datasheet describes pneumatic backrest adjustment with three modes."},{"q":"What uses does the manufacturer indicate?","a":"Dialysis, blood collection, respiratory and cardiac care."},{"q":"Where can I download the Reclining Chair SKE941 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Saikang Medical PDF (in Spanish)."}],"seo_keywords_es":["silla reclinable para diálisis","silla reclinable SKE941 Saikang","sillón toma de muestras Colombia","recliner neumático hospitalario","silla diálisis con bandeja","sillón procedimientos clínicos","ficha técnica SKE941"],"seo_keywords_en":["dialysis recliner chair","SKE941 Saikang recliner","blood collection recliner Colombia","pneumatic hospital recliner","dialysis chair with tray","clinical procedure recliner","SKE941 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKE941_Recliner-Chairs-for-Elderly_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-reclinable-ref-ske941-saikang';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/saikang-medical/sks008-abssteel-bedside-table-saikangmedical-es.pdf',
  descripcion_larga_es = $d$La mesita de noche hospitalaria ABS Saikang SKS008 (500 × 510 × 705 mm) combina cuerpo de acero con pulverizado plástico de alta calidad y encimeras, cajones y puertas de ABS inyectado: fuerte, resistente a la oxidación y fácil de limpiar. Entre el cajón y el tablero hay una tabla de comedor extraíble de dos capas internas con gran espacio de almacenamiento.

Ganchos para toallas ocultos, ruedas silenciosas anti-enrollamiento y un diseño pensado para no deformarse completan una mesita de noche hospitalaria práctica para habitaciones en Colombia.

Materiales mixtos acero/ABS documentados en ficha: durabilidad visible y mantenimiento sencillo para compras de piso.$d$,
  descripcion_larga_en = $d$The Saikang SKS008 bedside cabinet (500 × 510 × 705 mm) combines a high-quality plastic-sprayed steel body with injection-moulded ABS tops, drawers and doors: strong, oxidation-resistant and easy to clean. Between the drawer and the top sits a pull-out dining board with two internal layers and generous storage.

Hidden towel hooks, quiet anti-winding casters and a design meant not to deform complete a practical hospital nightstand for rooms in Colombia.

Datasheet-documented mixed steel/ABS materials: visible durability and simple maintenance for floor purchasing.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"SKS008"},{"clave":"Fabricante","grupo":"Identificación","valor":"Jiangsu Saikang Medical Equipment Co., Ltd."},{"clave":"Dimensiones externas","grupo":"Dimensiones","valor":"500 x 510 x 705 mm"},{"clave":"Encimera, cajones y puertas","grupo":"Material","valor":"ABS inyectado"},{"clave":"Extras","grupo":"Configuración","valor":"Tabla de comedor extraíble; ganchos para toallas ocultos"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Estructura ABS inyección"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Percheros ajustables"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Tabla para comer"},{"clave":"Característica","grupo":"Catálogo IME","valor":"Ruedas"}]$j$::jsonb,
  aplicaciones_es = ARRAY(SELECT jsonb_array_elements_text($j$["Habitaciones de hospitalización","Almacenamiento y comidas en cama","Pisos de enfermería","Dotación de mobiliario auxiliar"]$j$::jsonb)),
  aplicaciones_en = ARRAY(SELECT jsonb_array_elements_text($j$["Inpatient rooms","Storage and in-bed meals","Nursing floors","Auxiliary furniture inventories"]$j$::jsonb)),
