bedside table","SKS008 Saikang nightstand","ABS bedside cabinet Colombia","patient nightstand with dining board","ABS steel room furniture","hospital ABS bedside table","SKS008 datasheet"],"ficha_fabricante":{"fabricante":"Saikang Medical","idioma":"es","url_origen":"https://saikangmedical.com/wp-content/uploads/2025/08/SKS008_ABSSteel-Bedside-Table_SaikangMedical_ES.pdf","descargada":"2026-10-02"}}$j$::jsonb
